insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('glacier-montana', '12A', 'Glacier National Park', 'United States', 'A 50-mile road over the Continental Divide, railway-era lodges, and a summer that runs from early July to the third Monday of October', 'future', 'verified', 'mountainValley', 'Greater Yellowstone', '{"hiking","wildlife","glamping","family","culture","parks"}', '{"alpine","dramatic","wild","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Going-to-the-Sun Road","source":"https://www.nps.gov/glac/planyourvisit/gtsrinfo.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"50 miles across the park, about 2 hours without stopping, topping out at Logan Pass at 6,646 feet; typically fully open from early July to the third Monday of October"},{"name":"Logan Pass - three-hour parking (2026 rule)","source":"https://www.nps.gov/glac/planyourvisit/visiting-loganpass-2026.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"no vehicle reservation in 2026; instead every private-vehicle space at Logan Pass was limited to three hours with a free timestamped kiosk permit, 1 July to 7 September 2026, enforced 24 hours a day"},{"name":"Logan Pass Shuttle (ticketed, 2026 pilot)","source":"https://www.nps.gov/glac/planyourvisit/shuttle-service-2026.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"ticketed-only shuttle with early-morning express routes to Logan Pass, 1 July to Labor Day 2026; $1 ticket on Recreation.gov, released 60 days ahead and the night before"},{"name":"Highline Trail and Hidden Lake Overlook","source":"https://www.nps.gov/glac/planyourvisit/visiting-loganpass-2026.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"the two Logan Pass hikes the NPS names: Hidden Lake Overlook fits inside three hours of parking, the Highline to Granite Park Chalet needs a shuttle ticket"},{"name":"Many Glacier Hotel","source":"https://www.glaciernationalparklodges.com/lodging/many-glacier-hotel/","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"Great Northern Railway hotel of 1914-15 on Swiftcurrent Lake, five storeys and 214 rooms and suites; open 5 June to 21 September 2026"},{"name":"Grinnell Glacier hike","source":"https://wereintherockies.com/grinnell-glacier-hike/","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"10.6 miles round trip with 1,600 feet of gain from Many Glacier, cut to about 7 miles by taking the two-lake boat across Swiftcurrent Lake and Lake Josephine"},{"name":"Red Bus Tours","source":"https://www.glaciernationalparklodges.com/red-bus-tours/","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"a fleet of 33 vintage 1930s buses, described by the operator as the oldest touring fleet anywhere; 16 passengers each, departing from lodges on both sides of the park, bookable for 2026"},{"name":"Glacier Park Boat Co. lake tours","source":"https://www.nps.gov/glac/planyourvisit/boat-trips-and-rentals.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the boat tours on Many Glacier, Two Medicine, Rising Sun (St. Mary Lake) and Lake McDonald, plus small-boat rentals at Apgar, Lake McDonald, Two Medicine and Many Glacier"},{"name":"Under Canvas Glacier, Coram","source":"https://www.undercanvas.com/camps/glacier/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"safari-style tents with wood-burning stoves about 7 miles from the west entrance; ensuite Deluxe and Suite tents and family kids-tent options; open 29 May to 14 September 2026"},{"name":"West Glacier and the Belton Chalet","source":"https://www.glacierparkcollection.com/lodging/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the west-entrance village with the Amtrak Belton station and the historic Belton Chalet across the street; Belton Chalet open 8 May to 11 October 2026"},{"name":"East Glacier and Glacier Park Lodge","source":"https://glaciermt.com/trains","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the Great Northern''s first big lodge (1912-13), across from the 1913 East Glacier Amtrak station; open 29 May to 27 September 2026"},{"name":"St. Mary Village","source":"https://www.glacierparkcollection.com/lodging/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"east-entrance base at the foot of Going-to-the-Sun Road, open 29 May to 5 October 2026; St. Mary Visitor Center is an east-side departure point for the Logan Pass shuttle"},{"name":"Whitefish","source":"https://explorewhitefish.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the resort town \"at the edge of Glacier National Park\", 12 miles from Glacier Park International Airport and an Empire Builder stop"},{"name":"Whitefish Winter Carnival LXVIII","source":"https://www.whitefishwintercarnival.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Whitefish''s winter carnival, dated 5-7 February 2027"},{"name":"North American Indian Days, Browning","source":"https://blog.glaciermt.com/north-american-indian-days-and-the-blackfeet-nation/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"one of the largest gatherings of US and Canadian tribes, held the second week of July at Stampede Park on the Blackfeet Reservation just east of the park"},{"name":"Granite Park Chalet","source":"https://www.nps.gov/glac/learn/historyculture/lodges-and-chalets.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"Great Northern backcountry chalet of 1914-15 on the Highline Trail; one of the two chalets the NPS says still function, and its guests are exempt from the Logan Pass overnight-parking ban"},{"name":"BaseGlamp, north of Whitefish","source":"https://business.whitefishchamber.org/list/member/baseglamp-5716","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"year-round site of 12 geodesic domes on 20 acres about 15 minutes north of Whitefish, with ensuite bathrooms, wood-burning stoves and outdoor cedar hot tubs (listing seen in search results)"},{"name":"ROAM Beyond Glacier, Columbia Falls","source":"https://www.roambeyond.travel/map-glacier","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"\"an immersive outdoor lodging experience\" of tiny Roaming Cabins on wheels at 2347 Middle Rd, Columbia Falls"},{"name":"Columbia Falls RV Park glamping tents","source":"https://www.columbiafallsrvpark.com/ways-to-stay/Tent-Sites.html","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"canvas wall tents with queen or king beds, air conditioning and heating, \"just 15 minutes from the west entrance\"; seasonal"},{"name":"North Forty Resort, Columbia Falls","source":"https://www.northfortyresort.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"family-owned log-cabin retreat on 40 acres with twenty-three cabins and a summer glamping tent sleeping up to 4 (seen in search results)"},{"name":"North American RV Park & Yurt Village, Coram","source":"https://visitmt.com/listing/north-american-rv-park-yurt-village-9344","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"family-run RV park with yurts and camping cabins about 5.5 miles from the west entrance, open April through October (listing seen in search results)"},{"name":"Lodgepole Gallery and Tipi Village, Blackfeet Reservation","source":"https://b2b.glaciermt.com/unique-lodging-accommodations-and-options-in-western-montana/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"11 tipis sleeping four each, with fire rings, bison dinners and cultural programmes of Native drumming and singing, east of the park"},{"name":"Glacier Grizzly Resort (tipis), near the east side","source":"https://www.glaciergrizzlyrv.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"listed with around 50 tipis on 250 acres about 11 miles from the St. Mary entrance; one listing reports it closed permanently, so its current status is NOT CONFIRMED (seen in search results)"},{"name":"NPS reservation campgrounds (8)","source":"https://www.nps.gov/glac/planyourvisit/reservation-campgrounds.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Apgar, Avalanche, Fish Creek, Many Glacier, Rising Sun, St. Mary, Sprague Creek and Two Medicine are reservation-only on Recreation.gov; the NPS says \"a majority of Glacier''s campgrounds require a reservation\""},{"name":"NPS first-come, first-served campgrounds","source":"https://www.nps.gov/glac/planyourvisit/camping-information.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Bowman Lake, Cut Bank, Kintla Lake, Logging Creek and Quartz Creek; vehicle combinations over 21 feet are not allowed at Cut Bank, Kintla Lake, Logging Creek and Quartz Creek, and Cut Bank uses Recreation.gov Scan & Pay (seen in search results)"},{"name":"West Glacier KOA Resort","source":"https://koa.com/campgrounds/west-glacier/site-type/lodging/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"KOA resort outside West Glacier with Deluxe Studio Cabins and Sky Deck cabins sleeping up to four, pools and staff-led activities (KOA page seen in search results; direct fetch refused)"},{"name":"St. Mary / East Glacier KOA Holiday","source":"https://koa.com/campgrounds/st-mary/site-type/lodging/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"KOA at the base of the park''s east side with upgraded RV sites and Deluxe Cabins with full baths (KOA page seen in search results; direct fetch refused)"},{"name":"Johnson''s of St. Mary","source":"https://glaciermt.com/listing/johnsons-of-st-mary","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"campground, cabins and RV park a quarter-mile from the St. Mary entrance, 82 RV and 75 tent sites, with a family-style cafe; open mid-May to mid-September (listing seen in search results)"},{"name":"San-Suz-Ed RV Park, West Glacier","source":"https://www.roverpass.com/c/san-suz-ed-rv-park-west-glacier-mt/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"RV park, campground and bed and breakfast at 11505 Highway 2 East, West Glacier, with full hookups and pull-through sites (listing seen in search results)"},{"name":"Glacier Peaks RV Park & Cabins, Columbia Falls","source":"https://glaciermt.com/listing/glacier-peaks-rv-park-cabins","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"60 RV spaces and cabins 3 miles west of Columbia Falls, about 30 minutes from the park (listing seen in search results)"},{"name":"Swan Mountain Outfitters horseback rides","source":"https://www.nps.gov/glac/planyourvisit/horseback-rides.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"the NPS-named horseback concessioner, riding from corrals at Many Glacier, Lake McDonald and Apgar; no rides in winter"},{"name":"Flathead River rafting, West Glacier","source":"https://www.nps.gov/glac/planyourvisit/rafttours.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"four companies the NPS lists - Glacier Guides and Montana Raft, Glacier Raft Company, Great Northern Resort and Wild River Adventures - run the Middle and North Forks of the Flathead under US Forest Service permits"},{"name":"Sun Tours, East Glacier Park","source":"https://glaciermt.com/listing/sun-tours","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Blackfeet interpretive tours over Going-to-the-Sun Road, guided by residents of the Blackfeet Reservation, with pickups in East Glacier Park, Browning and the St. Mary valley (listing seen in search results)"},{"name":"Bike and e-bike rental, Apgar and West Glacier","source":"https://www.flatheadoutdoors.com/ebike-rentals-tours/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Flathead Outdoors rents hybrid bikes and e-bikes at West Glacier and in Apgar Village; Going-to-the-Sun Road opens to cyclists for a spring window before cars (seen in search results)"},{"name":"Polebridge Mercantile, North Fork","source":"https://dailyinterlake.com/news/2023/jun/04/recounting-rich-history-polebridge-mercantile/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"1914 off-grid general store and bakery near the park''s north-west corner, known for its huckleberry bear claws (seen in search results)"},{"name":"Glacier Distilling Company, Coram","source":"https://www.glacierdistilling.com/visit-us","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"craft distillery tasting room about 10 minutes from the west entrance, maker of Bearproof huckleberry whiskey and Logan Pass single malt (seen in search results)"},{"name":"Whitefish Mountain Resort, summer","source":"https://skiwhitefish.com/event/whitefish-mountain-resort-summer-daily-operations-begin/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"scenic lift or gondola to a summit with views of Glacier''s peaks, alpine slides and an aerial adventure park; summer 2026 daily operations ran 13 June to 7 September (seen in search results)"},{"name":"The Huckleberry Patch, Hungry Horse","source":"https://www.huckleberrypatch.com/","accessed":"2026-10-02","si":["culinary","family","senior"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Huckleberry specialist at the only stoplight in Hungry Horse with its own cannery, bakery, sweetshop and pantry (plus Flathead cherry goods) and a lunch and dinner menu; summer hours 9am-9pm."},{"name":"Park Cafe and Grocery, St. Mary","source":"https://parkcafeandgrocery.com/","accessed":"2026-10-02","si":["culinary","family","senior"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Cafe at the park''s east entrance, established in the early 20th century and known for its pies (apple, huckleberry, pecan, rhubarb); cafe 8am-9pm daily."},{"name":"Serrano''s Mexican Restaurant, East Glacier","source":"https://www.serranosmexican.com/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"Toast (online takeout ordering); dine-in reservations not observed","tier_absent_reason":"not-sold","blurb":"Historic cantina serving traditional and contemporary Mexican dishes, fajitas and margaritas, with outdoor seating and mountain views; 5-9pm."},{"name":"Backslope Brewing, Columbia Falls","source":"https://www.backslopebrewing.com/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"walk-in, no reservations; Toast for online food orders","tier_absent_reason":"not-sold","blurb":"Family-friendly brewery and kitchen ''in the shadow of Glacier National Park'', open Tuesday to Saturday 11am-8pm."},{"name":"Spotted Bear Spirits, Whitefish","source":"https://www.spottedbearspirits.com/","accessed":"2026-10-02","si":["culinary","group","romance"],"booking_route":"own form (reservations through website)","tier_absent_reason":"not-sold","blurb":"Downtown craft distillery and cocktail lounge across from Depot Park making Montana whiskey, huckleberry vodka and gin; $2 per bottle of Midnight Forest goes to Backcountry Hunters and Anglers."},{"name":"Tupelo Grille, Whitefish","source":"https://www.tupelogrille.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"phone only 406.862.6136","tier_absent_reason":"not-sold","blurb":"Downtown Southern-cuisine restaurant established in 1995, with an award-winning wine list and Sunday brunch."},{"name":"Latitude 48, Whitefish","source":"https://www.latitude48bistro.com/","accessed":"2026-10-02","si":["culinary","romance","group"],"booking_route":"OpenTable, or phone 406-863-2323","tier_absent_reason":"not-sold","blurb":"Central Avenue bistro of locally sourced shareable plates, wood-fired pizzas, steaks and oysters, with a Red Room happy hour."},{"name":"Loula''s Cafe, Whitefish","source":"https://www.loulaswhitefish.com/","accessed":"2026-10-02","si":["culinary","family","senior"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Family-owned scratch kitchen in the lower level of the historic Masonic temple, using Montana beef and local produce, known for homemade pies including huckleberry/cherry."},{"name":"Cafe Kandahar, Kandahar Lodge, Whitefish Mountain Resort","source":"https://www.kandaharlodge.com/","accessed":"2026-10-02","si":["culinary","romance","sports"],"booking_route":"phone 406-862-6098 or email (no online route observed)","tier_absent_reason":"not-sold","blurb":"Fine-dining chop-house kitchen at Kandahar Lodge on the mountain (the site also brands it Buchanan''s at Kandahar), with a limited menu in the lodge bar."},{"name":"Whitefish Farmers Market","source":"https://www.whitefishfarmersmarket.org/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Tuesday evening market (5-7:30pm) at Depot Park on Central Avenue, June 2 to September 29, 2026, running since 2003 with farmers, food trucks and artisans."},{"name":"Kalispell Farmers Market","source":"https://www.kalispellfarmersmarket.org/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Saturday market (9am-12:30pm) at Flathead Valley Community College, running more than 50 years; 2026 season May 2 to October 17, plus a Harvest Holiday Market on October 17."},{"name":"SunRift Beer Company, Kalispell","source":"https://www.sunriftbeer.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Downtown Kalispell taproom brewing beer ''inspired by the life we all crave here in the Flathead Valley'', with food menus."}],"faq":[{"q":"Do you need a vehicle reservation for Glacier National Park?","a":"Not in 2026. The NPS states vehicle reservations were not required in 2026, including in Many Glacier, Two Medicine and the North Fork. Instead, from 1 July to 7 September 2026, Logan Pass parking was limited to three hours and the Logan Pass shuttle required a ticket. Rules for 2027 were not established in this build.","source":"https://www.nps.gov/glac/learn/news/glacier-national-park-announces-2026-summer-operations.htm","accessed":"2026-10-02"},{"q":"When is Going-to-the-Sun Road open?","a":"The NPS says the road has been fully open by early July and is typically fully open until the third Monday of October, with exact dates depending on snow and weather. The section from West Glacier to Lake McDonald Lodge is plowed year-round, weather permitting.","source":"https://www.nps.gov/glac/planyourvisit/gtsrinfo.htm","accessed":"2026-10-02"},{"q":"How much does it cost to enter Glacier National Park?","a":"In 2026 a 7-day private vehicle pass is $35 ($25 in winter), a 7-day per-person pass is $20, and the Glacier annual pass is $70. International visitors aged 16 and over pay an extra $100 per person unless they hold an annual or America the Beautiful pass.","source":"https://www.nps.gov/glac/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"What is the closest airport to Glacier National Park?","a":"Glacier Park International Airport (FCA) in Kalispell, 30 miles from the West Entrance and 12 miles from Whitefish. Amtrak''s Empire Builder also stops at East Glacier, West Glacier and Whitefish.","source":"https://www.glacierparkcollection.com/plan-your-trip/getting-here/","accessed":"2026-10-02"},{"q":"Are there bears in Glacier National Park?","a":"Yes. The NPS states researchers estimate Glacier provides habitat for nearly one thousand bears, that bear spray has been shown to be the most effective deterrent, and that approaching within 100 yards of bears or wolves is prohibited.","source":"https://www.nps.gov/glac/planyourvisit/bears.htm","accessed":"2026-10-02"},{"q":"When is Under Canvas Glacier open?","a":"29 May to 14 September in 2026 and 28 May to 13 September in 2027. The camp is in Coram, about 7 miles from the park''s west entrance.","source":"https://www.undercanvas.com/camps/glacier/","accessed":"2026-10-02"}],"seo":{"meta_title":"Glacier National Park: Going-to-the-Sun Road, Logan Pass & Many Glacier | TravelWell","meta_description":"When Going-to-the-Sun Road opens, what the 2026 Logan Pass rules were, where to stay from Many Glacier to Under Canvas, and the gateway towns around the park.","slug":"glacier-national-park-montana","primary_keyword":"Glacier National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Glacier National Park, Montana"}}'::jsonb, 86),
  ('death-valley-california', '12A', 'Death Valley National Park', 'United States', 'The lowest point in North America, a Gold Tier dark-sky park, and a ring of ghost towns, hot springs and date farms across the California-Nevada line', 'future', 'verified', 'mountainValley', 'The Great Basin & Nevada', '{"hiking","adventure","culture","family","parks"}', '{"dramatic","remote","rugged","wild"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Badwater Basin","source":"https://www.nps.gov/places/badwater-basin.htm","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed - park entrance fee only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The lowest point in North America is a surreal landscape of vast salt flats\" - 282 feet below sea level, nearly 200 square miles of salt; an ADA accessible ramp leads to a wooden boardwalk; 1 mile round trip to the salt flat edge; 30 minutes south of Furnace Creek; NPS: summer hiking discouraged after 10 AM"},{"name":"Artists Drive and Artists Palette","source":"https://www.nps.gov/places/artists-palette.htm","accessed":"2026-10-02","si":["senior","family","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a one-way scenic loop of about 30 minutes off Badwater Road, starting 8.5 miles south of the Highway 190 junction; \"a length restriction of 25 ft. (7.6 m) due to sharp bends and large dips\""},{"name":"Dantes View","source":"https://www.nps.gov/places/dantes-view.htm","accessed":"2026-10-02","si":["hiking","romance","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a viewpoint 5,575 feet above Badwater Basin on the Black Mountains ridge, \"an unparalleled view of the swirling white salt flats\", 45 minutes from Furnace Creek, popular at sunrise and sunset, with an 8-mile round-trip ridge trail toward Mt. Perry"},{"name":"Mesquite Flat Sand Dunes","source":"https://www.nps.gov/places/mesquite-flat-sand-dunes.htm","accessed":"2026-10-02","si":["hiking","family","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a dune field just east of Stovepipe Wells Village off CA-190, 2 miles round trip to the tallest dune (185 feet gain), \"dramatic shadows at sunrise and sunset\"; no official trails; pets prohibited; NPS: \"HIKING NOT ADVISED AFTER 10 AM IN THE SUMMER\""},{"name":"Ubehebe Crater","source":"https://www.nps.gov/places/ubehebe-crater.htm","accessed":"2026-10-02","si":["hiking","adventure","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a maar volcano about half a mile across and 500-777 feet deep, about 2,100 years old; 1.5-mile, 1-hour moderate rim hike with 500 feet of gain; paved overlook lot for buses and large RVs; about an hour from Furnace Creek"},{"name":"Golden Canyon","source":"https://www.nps.gov/deva/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 3-mile moderate-to-strenuous canyon hike rated by the NPS, and in winter a ranger-led Golden Canyon Hike of about three-quarters of a mile; NPS: \"Summer temperatures can be dangerous in the park''s lower elevations\""},{"name":"Harmony Borax Works and Salt Creek Interpretive Trail","source":"https://www.nps.gov/deva/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["senior","family","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two easy short walks - Harmony Borax Works 0.4 mile on a paved path through mining history (a ranger walk in winter, and an NPS night-sky pick) and the 0.5-mile Salt Creek Interpretive Trail"},{"name":"Mosaic Canyon and Natural Bridge","source":"https://www.nps.gov/deva/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","adventure","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Mosaic Canyon, 4 miles, moderate to difficult, and Natural Bridge, an easy 1 mile - two of the NPS''s named canyon walks"},{"name":"Telescope Peak","source":"https://www.nps.gov/deva/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s hardest named day hike, 12.2 miles, rated difficult, to the 11,049-foot summit that rises above Badwater; Wildrose Peak (7.9 miles) is the shorter difficult alternative"},{"name":"Backcountry roads: the Racetrack and Titus Canyon","source":"https://www.nps.gov/deva/planyourvisit/backcountryroads.htm","accessed":"2026-10-02","si":["adventure","expedition"],"booking_route":"none needed; jeep hire via Farabee''s","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Death Valley has more miles of roads than any other national park\" - nearly 1,000 miles across 3.4 million acres; high-clearance or 4WD required on rough routes, NPS asks for \"2 full size spare tires\" and warns \"rescue is likely to be extremely delayed\"; Titus Canyon closed in sections from October 2, 2026"},{"name":"Ranger programs (mid-November to mid-April)","source":"https://www.nps.gov/deva/planyourvisit/ranger-programs.htm","accessed":"2026-10-02","si":["family","culture","senior","hiking"],"booking_route":"none needed; Paleontology Hikes via recreation.gov when offered","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"free, no-reservation talks and walks from December to March - Badwater, Harmony Borax Works, Golden Canyon, Sand Dunes, a Night Sky Talk at Furnace Creek and family programmes; \"No outdoor formal programs are scheduled during summer due to extreme heat\"; ticketed Paleontology Hikes not offered in 2026"},{"name":"Gold Tier dark skies","source":"https://www.nps.gov/deva/night-exploration.htm","accessed":"2026-10-02","si":["adventure","romance","family","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Gold Tier, the highest classification from the International Dark-Sky Association; rangers name Mesquite Flat Sand Dunes, Harmony Borax Works, Badwater Basin and Ubehebe Crater as top spots; an annual spring Dark Sky Festival with NASA speakers"},{"name":"The Inn at Death Valley, Furnace Creek","source":"https://www.oasisatdeathvalley.com/","accessed":"2026-10-02","si":["romance","senior","wellness"],"booking_route":"own engine (secure.oasisatdeathvalley.com/booking/lodging)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"An elegant hideaway since 1927\", a AAA four-diamond resort for more than 37 years, with natural springs, palms, new casitas, a spring-fed pool and fine dining; the Oasis also lists horseback riding and a spa"},{"name":"The Ranch at Death Valley, Furnace Creek","source":"https://www.oasisatdeathvalley.com/","accessed":"2026-10-02","si":["family","group","senior"],"booking_route":"own engine (secure.oasisatdeathvalley.com/booking/lodging)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the family-friendly half of the Oasis, next to the NPS visitor centre on Highway 190, after a $200 million renovation: rooms with private patios, a spring-fed pool, a date-palm town square and several places to eat"},{"name":"Stardust Astrotours at the Oasis","source":"https://www.oasisatdeathvalley.com/plan/stargazing/","accessed":"2026-10-02","si":["adventure","romance","family","senior"],"booking_route":"not observed (price and engine not shown on the Oasis or stardustastrotours.com pages; Oasis 800-236-7916)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided small-group night sky tours with astronomers, departing from the Oasis resort: laser-guided constellations, high-powered telescopes, all equipment provided; the Oasis cites Bortle Class 2 darkness and the Leonids (November 16-18, 2026) and Geminids (December 13, 2026)"},{"name":"Furnace Creek Golf Course","source":"https://www.oasisatdeathvalley.com/activities/","accessed":"2026-10-02","si":["sports","senior"],"booking_route":"tee times via oasisatdeathvalley.com/furnace-creek-golf-course/","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"billed as \"the lowest elevation course in the world\", at 214 feet below sea level, shared by guests of the Inn and the Ranch"},{"name":"Stovepipe Wells Village","source":"https://www.stovepipedeathvalley.com/","accessed":"2026-10-02","si":["family","adventure","group"],"booking_route":"StayNTouch (stovepipewellsvillagehotel.ibe.stayntouch.com); RV sites via its website","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the in-park concession at 51880 Highway 190, run by POWDR: air-conditioned rooms including accessible rooms, full-hookup RV sites, tent sites, a pool, a restaurant and saloon, and a 24-hour gas station"},{"name":"Panamint Springs Resort","source":"https://www.nps.gov/deva/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"not observed (panamintsprings.com showed a bot check)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"named by the NPS as an in-park private operation with \"resort accommodations, camping, a restaurant and gas station\" on the park''s west side; 775-482-7680"},{"name":"Furnace Creek Campground","source":"https://www.nps.gov/deva/planyourvisit/camping-in-death-valley.htm","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"recreation.gov (October 15 to April 15)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the NPS campground open year-round that \"takes reservations for October 15th - April 15th season\" on recreation.gov up to 6 months ahead; NPS: Furnace Creek and Texas Springs \"are typically full on weekends and holidays\""},{"name":"Sunset, Texas Springs and the first-come campgrounds","source":"https://www.nps.gov/deva/planyourvisit/camping-in-death-valley.htm","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"none - first-come, first-served","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"every NPS campground except Furnace Creek is first-come, first-served - Sunset, Texas Springs, Stovepipe Wells, Mesquite Spring, Wildrose, Mahogany Flat, Thorndike (Emigrant closed indefinitely); \"The park''s largest campground, Sunset, almost always has sites available, even in peak season\""},{"name":"Farabee Jeep Rentals & Tours, Furnace Creek","source":"http://farabeejeeps.com/","accessed":"2026-10-02","si":["adventure","group","family"],"booking_route":"phone/email only (760-786-9872)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"named by the NPS as the Furnace Creek jeep outfitter; daily guided tours to the Racetrack, Echo, Cottonwood/Marble and Hole in the Wall with snacks and water, and self-drive rentals on Echo, Hole in the Wall, Cottonwood/Marble and Goler"},{"name":"Rhyolite ghost town, Beatty, Nevada","source":"https://www.blm.gov/visit/rhyolite-historic-area","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a BLM-managed former gold-mining boomtown on NV 374 with the Cook Bank Building, \"one of the most photographed buildings in the West\", and \"Nevada''s best preserved ''bottle house''\"; day use only; listed by the NPS among nearby attractions"},{"name":"Goldwell Open Air Museum, Rhyolite","source":"https://www.goldwellmuseum.org/","accessed":"2026-10-02","si":["culture","family","romance"],"booking_route":"none needed; donations on its website","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"seven monumental outdoor sculptures by Belgian artists led by the late Albert Szukalski, including \"Last Supper\" and \"Lady Desert\", at 1 Golden St; grounds open 24 hours, visitor centre about Monday-Saturday 10-4"},{"name":"Marta Becket''s Amargosa Opera House and Hotel, Death Valley Junction","source":"https://www.amargosaoperahouse.org/","accessed":"2026-10-02","si":["culture","senior","romance"],"booking_route":"phone/front desk only (760-852-4441)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a historic desert opera house and hotel at Highway 127 and State Line Road, with daily guided tours at 9 am and 6 pm ($20 adults, $10 children), a separate cafe, and occasional shows"},{"name":"China Ranch Date Farm, Tecopa","source":"https://www.chinaranch.com/","accessed":"2026-10-02","si":["culinary","hiking","family"],"booking_route":"walk-in; online store on chinaranch.com","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a date farm at #8 China Ranch Rd selling several California date varieties and its own hybrids, date nut bread, muffins and cookies from its bakery, with trails to abandoned mines, the Old Spanish Trail and the Tonopah & Tidewater railroad bed"},{"name":"Tecopa Hot Springs & Campground","source":"https://tecopahotspringsandcampground.com/","accessed":"2026-10-02","si":["wellness","senior"],"booking_route":"RoverPass","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an Inyo County park run by concessionaire Flippin-Hamrick: 30 partial-hookup RV sites and over 200 dry sites, tent camping, and two bathhouses with separate men''s and women''s hot mineral pools at about 102°F; nude bathing \"per local code\""},{"name":"Shoshone Village","source":"https://www.shoshonevillage.com/","accessed":"2026-10-02","si":["family","culture","senior"],"booking_route":"Reson on the Web (resontheweb.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the Shoshone Inn, RV park, campground and vacation rentals around a warm springs swimming pool, with the Crowbar Cafe & Saloon and the Shoshone Museum, an interpretive centre for the Amargosa and Death Valley region; one ADA-accessible bungalow"},{"name":"Tarantula Ranch, Beatty","source":"https://www.hipcamp.com/en-US/land/nevada-tarantula-ranch-2ejhv6lz","accessed":"2026-10-02","si":["glamping","wine","romance","group"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an 8-acre Mojave Desert vineyard property with three teardrop-trailer glamping units, five RV/tent sites named for grape varietals, a shared bathhouse, outdoor kitchen and a \"Wine Hall\"; Star Host, 98% recommended"},{"name":"Falcon Cottage (Death Valley Desert Cottage), Pahrump","source":"https://www.hipcamp.com/en-US/land/nevada-death-valley-desert-cottage-pool-6p0hywdn","accessed":"2026-10-02","si":["glamping","family"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a cabin for up to six with a private unheated pool (comfortable May-October), stone fire pit, grills, fibre WiFi, and crib and high chair on request"},{"name":"Miss Kathy''s Short Branch, Crystal, Nevada","source":"https://www.hipcamp.com/en-US/land/nevada-miss-kathy-s-short-branch-qeoh00ek","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a western-decor motel-room cabin for two with private shower, air conditioning, StarLink WiFi and pets on leash, twenty minutes from Ash Meadows and Devil''s Hole and about twenty minutes from Pahrump"},{"name":"Alabama Hills, Lone Pine","source":"https://lonepinechamber.org/sightseeing-in-the-alabama-hills/","accessed":"2026-10-02","si":["adventure","hiking","culture"],"booking_route":"none needed; free BLM camping permit","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"golden granite boulders rising up from the desert floor\" and rock arches about 3 miles west of Lone Pine where Movie Road meets Whitney Portal Road, with Mobius Arch and over 400 films shot since the 1920s; BLM camping needs a free permit"},{"name":"Museum of Western Film History, Lone Pine","source":"https://museumofwesternfilmhistory.org/","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"America''s only Western Film Museum\" at 701 S. Main Street, open daily 9-5 for an $8 suggested donation, covering over 400 films shot in the Eastern Sierra; hosts the Lone Pine Film Festival each October"}],"faq":[{"q":"Do I need a reservation to enter Death Valley National Park?","a":"No. The NPS states that no reservation is required to enter the park. A private vehicle pays $30 for 7 days.","source":"https://www.nps.gov/deva/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I reserve a campsite in Death Valley?","a":"Only at Furnace Creek, which takes reservations on recreation.gov for the October 15 to April 15 season, up to 6 months ahead. All other NPS campgrounds are first-come, first-served; the NPS says Sunset, the largest, almost always has sites available, even in peak season.","source":"https://www.nps.gov/deva/planyourvisit/camping-in-death-valley.htm","accessed":"2026-10-02"},{"q":"Is Scotty''s Castle open?","a":"No. As of the NPS update of September 28, 2026, Bonnie Clare Road and Scotty''s Castle are closed due to flood recovery work, with no access permitted, including pedestrians.","source":"https://www.nps.gov/deva/planyourvisit/conditions.htm","accessed":"2026-10-02"},{"q":"Is Titus Canyon Road open?","a":"Not in full. The NPS lists the one-way section closed from October 2, 2026 to May 2027 and the two-way section closed from October 27 to December 2026.","source":"https://www.nps.gov/deva/planyourvisit/conditions.htm","accessed":"2026-10-02"},{"q":"When do ranger programs run?","a":"From mid-November to mid-April, with daily talks and walks December to March. The NPS says no outdoor formal programs are scheduled during summer due to extreme heat.","source":"https://www.nps.gov/deva/planyourvisit/ranger-programs.htm","accessed":"2026-10-02"},{"q":"Is Death Valley good for stargazing?","a":"The NPS states the park holds Gold Tier, the highest classification from the International Dark-Sky Association, and names Mesquite Flat Sand Dunes, Harmony Borax Works, Badwater Basin and Ubehebe Crater as top spots.","source":"https://www.nps.gov/deva/night-exploration.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Death Valley National Park: Badwater, Dunes, Dark Skies & Where to Stay | TravelWell","meta_description":"Badwater, the dunes, Gold Tier dark skies, current road closures, NPS campgrounds and where to stay from Furnace Creek to Tecopa hot springs and Beatty glamping.","slug":"death-valley-national-park-california","primary_keyword":"Death Valley National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Death Valley National Park, California"}}'::jsonb, 87),
  ('great-basin-nevada', '12A', 'Great Basin National Park', 'United States', 'Lehman Caves, bristlecone pines and Gold Tier dark skies', 'future', 'verified', 'mountainValley', 'The Great Basin & Nevada', '{"hiking","adventure","family","senior","group","parks"}', '{"remote","alpine","rugged","serene"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Lehman Caves","source":"https://www.nps.gov/grba/planyourvisit/lehman-caves-tours.htm","accessed":"2026-10-03","si":["adventure","family","group"],"booking_route":"Recreation.gov (Lehman Caves Tours ticket facility 251853) or limited walk-up tickets at the Lehman Caves Visitor Center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"Passageways in the marble rock are filled with beautiful speleothems including stalactites, stalagmites, popcorn, and cave bacon.\" Ranger tours only: Lodge Room (60 min, 0.4 mi, Easy) $12 adult / $6 youth; Grand Palace (90 min, 0.6 mi, Moderate, 69 stairs) $15 / $8; \"Cave tours are limited to 20 visitors each\"; \"The cave naturally remains around 52ºF (11ºC)\"; \"White Nose Syndrome Screening is mandatory\"."},{"name":"Wheeler Peak Bristlecone Grove (Bristlecone Trail)","source":"https://www.nps.gov/thingstodo/hike-to-the-wheeler-peak-bristlecone-grove.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail; no entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"2.8 miles, 600 ft gain from 9,890 ft, Moderate, 1.5-3 hours from the Bristlecone Trailhead at the end of the Scenic Drive, to \"the oldest living organisms in the world\"; the grove once held \"the Prometheus Tree, the oldest non-clonal organism on earth\", removed in 1964. The Glacier Trail continues beyond the grove."},{"name":"Wheeler Peak Scenic Drive","source":"https://www.nps.gov/grba/planyourvisit/wheeler-peak-scenic-drive.htm","accessed":"2026-10-03","si":["motoring","senior","family"],"booking_route":"none needed - free park road","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"A 12-mile \"out and back road\" gaining \"over 4,000 feet in elevation\" to \"an elevation exceeding 10,000 feet above sea level\", with pullouts on Mount Moriah, Lehman Creek, Wheeler Peak, Doso Doyabi Peak and the Snake Valley - the \"equivalent of driving from Baker, Nevada, to the frozen Yukon\". Usually open by Memorial Day weekend; no vehicles or trailers over 24 feet beyond mile marker 3."},{"name":"Ranger astronomy programmes at the Astronomy Amphitheater","source":"https://www.nps.gov/grba/planyourvisit/astronomy-programs.htm","accessed":"2026-10-03","si":["family","senior","group","romance"],"booking_route":"none needed - free, first come at the amphitheater by the Lehman Caves Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"roughly between Memorial Day and Labor Day, Great Basin Astronomy Rangers lead programs at the Astronomy Amphitheater every Thursday through Sunday\": a thirty-minute talk then an hour and a half at the telescopes; \"Programs are free and require no reservation, though there is a maximum capacity.\" \"The Great Basin Observatory is the only research grade observatory in a national park.\""},{"name":"Stargazing on your own in a Dark Sky Park","source":"https://www.nps.gov/grba/planyourvisit/great-basin-stargazing.htm","accessed":"2026-10-03","si":["romance","family","senior"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"some of the darkest skies in the lower 48 states\"; the NPS names the Astronomy Amphitheater, Mather Overlook on the Scenic Drive, the Baker Archaeological Site and the Ranching Exhibit on Highway 488 - \"none of the locations above allow overnight camping.\" Allow \"up to thirty minutes for the human eye to adjust to the darkness\"."},{"name":"Alpine Lakes Loop","source":"https://www.nps.gov/thingstodo/hike-the-alpine-lakes-loop.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"2.7 miles, 440 ft gain from 9,890 ft, rated Easy, 1.5-3 hours: \"this loop hike passes by two alpine lakes\" - Teresa and Stella - \"all while going through alpine meadows and coniferous forests.\" Links with the Bristlecone Trail for 4.1 miles. \"Potable water is not available along the Wheeler Peak Scenic Drive.\""},{"name":"Accessible Gothic Palace Tour","source":"https://www.nps.gov/grba/planyourvisit/lehman-caves-tours.htm","accessed":"2026-10-03","si":["senior","family"],"booking_route":"Recreation.gov (cave tour 195) or walk-up at the Lehman Caves Visitor Center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":7,"blurb":"30 minutes, 0.3 miles, no stairs, \"intended for persons with limited mobility\"; $8 adult, $4 youth (5-15), under 5 free. \"Access Pass and Senior Pass holders are entitled to a 50% discount on cave tour tickets for the cardholder only.\""},{"name":"Introduction to Wild Caving Tour","source":"https://www.nps.gov/grba/planyourvisit/lehman-caves-tours.htm","accessed":"2026-10-03","si":["adventure","group"],"booking_route":"Recreation.gov (cave tour 10253672)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":8,"blurb":"180 minutes, 1.5 miles, \"Strenuous\" with scrambling and belly crawling; adults only, $40. Separately, seven wild caves are open by permit and \"Permits must be submitted at least two weeks before the intended caving trip\" (nps.gov/grba permits page)."},{"name":"Junior Ranger and Night Explorer booklets","source":"https://www.nps.gov/grba/learn/kidsyouth/junior-ranger.htm","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"none needed - free download","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Learn about the Great Basin using this booklet. Explore the life of a bristlecone, deep caves, and other fun subjects with the help of Baby Raven.\" The Junior Ranger Night Explorer booklet earns a Dark-Sky patch with \"star trails and a bristlecone\"; booklets download from the park site, and \"rangers are not able to mail any junior ranger materials\"."},{"name":"Evening ranger programmes","source":"https://www.nps.gov/grba/planyourvisit/rangerprograms.htm","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"none needed - times posted at the Lehman Caves Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Rangers provide evening programs in the park between Memorial Day and Labor Day on a number of topics\"; \"During the summer months, rangers present programs for all ages at the Lehman Caves Visitor Center almost daily.\""},{"name":"Wheeler Peak Campground","source":"https://www.recreation.gov/api/camps/campgrounds/10088563","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":11,"blurb":"At nearly 10,000 feet beneath Wheeler Peak and Doso Doyabi, with \"paved parking spurs, picnic tables, campfire rings and grills along with vault toilets\"; reservable \"from late June through Labor Day weekend\"; \"Neither vehicles over 24 feet in length nor towed units over 24 feet in length are permitted\"; $20 a night, 50% off with Senior or Access passes."},{"name":"Upper Lehman Creek Campground","source":"https://www.recreation.gov/api/camps/campgrounds/10101374","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":12,"blurb":"At 7,500 feet among ponderosa pine and white fir beside \"a clear mountain stream\"; paved parking spurs; \"The nightly rate is $20.\" \"There is no potable water available at Upper Lehman Creek Campground.\""},{"name":"Lower Lehman Creek Campground","source":"https://www.recreation.gov/api/camps/campgrounds/10101362","accessed":"2026-10-03","si":["motoring","hiking","senior"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"\"perfect for RVs, with large, paved, pull-through parking at six of the nine camping sites\" at 7,300 feet; unstaffed, no potable water. The NPS: \"Winter camping is available in the Lower Lehman Creek Campground\" (visiting-in-winter page). $10 dump fee at the Visitor Center (fees page)."},{"name":"Grey Cliffs group campsites","source":"https://www.recreation.gov/api/camps/campgrounds/251958","accessed":"2026-10-03","si":["group","family","hiking"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"\"The campground is tucked beside limestone cliffs and set amongst pinyon pines\"; \"Groups utilizing a group campsite must include a minimum of 9 persons and cannot exceed a maximum group size of 16 persons per site\"; group sites $30 a night (individual sites $20); \"The campground cannot accommodate RVs or trailers\"; reservations \"from Memorial Day through September.\""},{"name":"Baker Creek Campground","source":"https://www.recreation.gov/api/camps/campgrounds/10354639","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"Recreation.gov","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"\"one of five developed campgrounds at Great Basin National Park\", in pinyon-juniper with \"shade, close to the Lehman Caves Visitor Center\" and backcountry trail access; $20 a night; \"This campground has a short reservation window to accommodate those last second travel plans.\""},{"name":"Baker-Johnson Lakes backcountry loop","source":"https://www.nps.gov/grba/learn/management/backcountry-regulations.htm","accessed":"2026-10-03","si":["adventure","hiking","group"],"booking_route":"free backcountry permit from the park (no quota, per the permits page)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"\"Backcountry permits are required for any backcountry camping on the Baker-Johnson Lakes Loop\"; both lakes sit above 10,000 feet where campfires are prohibited and portable stoves must be used; \"Group size in the backcountry is limited to 12 persons and/or 6 pack animals.\""},{"name":"Lexington Arch","source":"https://www.nps.gov/grba/planyourvisit/lexington-arch-trails.htm","accessed":"2026-10-03","si":["hiking","adventure","overland"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"Hypothesized to be left over from an ancient cave system, Lexington Arch is one of the most incredible features of Great Basin, replicated nowhere else in the park.\" The road is \"almost entirely gravel and dirt\"; \"4WD is recommended on this road, and high clearance is absolutely necessary.\" Leashed pets are allowed on this trail (nps.gov/grba pets page)."},{"name":"Winter ski touring and snowshoeing on the Scenic Drive","source":"https://www.nps.gov/grba/planyourvisit/visiting-in-winter.htm","accessed":"2026-10-03","si":["ski","adventure"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"\"The Wheeler Peak Scenic Drive closes to vehicle traffic, but remains open to skiers and snowshoers\"; \"Novice skiers can find gentle slopes for touring or experienced ski mountaineers can challenge their skills on steep and deep backcountry runs.\" Free camping in the closed Wheeler Peak Campground in winter."},{"name":"Great Basin Cafe and Gift Shop","source":"https://www.nps.gov/grba/planyourvisit/restaurants.htm","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; (775) 234-7200","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":19,"blurb":"\"located at the Lehman Caves Visitor Center\", \"open for the summer season, April through October\"; \"The Cafe is the only restaurant within the boundaries of Great Basin National Park\". (775) 234-7200."},{"name":"Water and a filter for the high desert","source":"https://www.nps.gov/grba/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":20,"blurb":"NPS: \"Carry plenty of water and drink it!\" \"All surface water should be chemically treated, boiled, or passed through a filter capable of eliminating harmful microbes and parasites, such as giardia, before drinking.\" On the Scenic Drive, \"Potable water is not available\" - the NPS suggests \"about one gallon per person per day\" (Alpine Lakes Loop page)."},{"name":"Hat and sunscreen above 10,000 feet","source":"https://www.nps.gov/grba/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":21,"blurb":"NPS: \"Sunburn is a common problem when hiking at high elevations\" because the thin atmosphere filters less; \"Wear a hat and sunscreen.\""},{"name":"Layered non-cotton clothing","source":"https://www.nps.gov/grba/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","ski"],"booking_route":"affiliate referral to Rab US (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"NPS: \"Avoid hypothermia by wearing appropriate, layered clothing. Do not wear cotton clothing, which becomes very cold when wet.\" \"It can snow any time of the year at high elevations\" (weather page), and the cave holds \"around 52ºF\" (cave tours page)."},{"name":"Red headlamp for the dark sky","source":"https://www.nps.gov/grba/planyourvisit/great-basin-stargazing.htm","accessed":"2026-10-03","si":["family","romance","hiking"],"booking_route":"affiliate referral to Black Diamond Equipment (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":23,"blurb":"NPS stargazing kit: a red flashlight or headlamp to \"preserve your night vision\", binoculars or a telescope, and a star chart or app; allow \"up to thirty minutes for the human eye to adjust to the darkness\"."},{"name":"Satellite communicator where phones fail","source":"https://www.nps.gov/grba/planyourvisit/safety.htm","accessed":"2026-10-03","si":["adventure","hiking","overland"],"booking_route":"affiliate referral to zoleo.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":24,"blurb":"NPS: \"Cell phone reception is not reliable in the park and surrounding areas. Do not rely on them!\" and on the directions page, \"Do not rely on navigation apps to guide to correct locations.\""},{"name":"Winter backcountry kit (shovel, beacon, probe)","source":"https://www.nps.gov/grba/planyourvisit/visiting-in-winter.htm","accessed":"2026-10-03","si":["ski","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":25,"blurb":"NPS winter list: a \"properly fitted backpack\", food, water, \"extra clothing (especially extra socks and gloves)\", and in avalanche terrain a \"snow shovel,\" \"avalanche beacon,\" and \"avalanche probe.\""},{"name":"Stargazer Inn","source":"https://stargazernevada.com/","accessed":"2026-10-03","si":["hiking","family","romance"],"booking_route":"own website booking (book.stargazernevada.com) or email","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"\"Stargazer Inn & Bristlecone General Store\" at 115 S. Baker Ave., Baker, NV 89311 - \"Rooms & Cabins\" at the gateway town; (775) 234-7323; booked online at book.stargazernevada.com or stay@stargazernevada.com. The NPS lists it \"Open January 1 - November 30\" (goods and services page)."},{"name":"Bristlecone General Store","source":"https://stargazernevada.com/bristlecone-general-store/","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"walk-in store","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":27,"blurb":"Baker''s store for \"outdoor gear, maps and good books; a grocery refueling station\" plus local artisans'' goods; October hours \"7 Days a Week 9am - 5pm\"; 115 S. Baker Ave."},{"name":"Whispering Elms Motel, Campground and RV Park","source":"https://www.whisperingelms.com/","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"own website booking (ResNexus)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"120 Baker Ave, Baker - \"6 miles from Great Basin National Park\": RV sites, tent camping and motel rooms, tank dumping and water fill-ups, EV chargers, and a lodge with pool table, shuffleboard and darts; \"Open Year-round!\" (the NPS page says \"Open spring - October 31\")."},{"name":"Great Basin Desert Camping & RV","source":"https://www.hipcamp.com/en-US/land/nevada-great-basin-desert-camping-rv-dw9hlx68","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"Baker: 5 RV-only sites with full hookups (\"30amp and 50 amp electricity, sewer and water\", \"back-in only\") and 5 RV/tent primitive sites; restrooms with showers and coin laundry; no campfires. Listed as \"one of the best Hipcamps to visit in 2026\"."},{"name":"Sacramento Pass Recreation Area (BLM)","source":"https://www.blm.gov/visit/sacramento-pass-rec-area","accessed":"2026-10-03","si":["hiking","motoring","family"],"booking_route":"none - free, first come first served","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay","activities"],"draw_rank":30,"blurb":"On Highway 50, \"40 miles east of Ely or 15 miles west of the Utah border\": \"10 sites with a 14-day limit\" in two loops, one accessible site in each; \"3 trail loops (closed to motorized use)... 6.5 miles total\", a 6-mile equestrian trail and \"A small pond for fishing\"; no potable water; \"Free, No Reservations, First Come First Serve\"."},{"name":"Bates Family Ranch cabins and campsites","source":"https://www.batesfamilyranch.com/","accessed":"2026-10-03","si":["family","group","motoring"],"booking_route":"own website booking system / Contact Us","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"Gandy, Utah, \"the headquarters for Crystal Ball Cave\" and \"Just 45 minutes from Great Basin National Park\": rustic \"Cabin Rentals | Campsites\" that \"Sleep 4-5 people\", \"self contained (no hookups) RV parking\" and \"newly remodeled restrooms with showers.\""},{"name":"Crystal Ball Cave","source":"https://www.batesfamilyranch.com/","accessed":"2026-10-03","si":["adventure","family","group"],"booking_route":"by appointment through the Bates Family Ranch website","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":32,"blurb":"A privately held cave at Gandy, Utah, toured from the Bates Family Ranch: \"By Appointment Only | Donations Welcome\". The local grotto of the National Speleological Society points visitors to the ranch for tour reservations (nnvgrotto.caves.org)."},{"name":"Hidden Canyon Retreat","source":"https://www.greatbasinpark.com/where-to-stay","accessed":"2026-10-03","si":["romance","hiking","senior"],"booking_route":"phone (775) 234-7172 (own site unreachable)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":33,"blurb":"Listed by the Great Basin Business and Tourism Council as a Bed & Breakfast; the NPS lists \"Hidden Canyon Ranch\" 14 miles south of Baker for \"Bed and breakfast, fly fishing, hiking\", (775) 234-7172. Its own website failed a certificate check when fetched."},{"name":"Sandra''s Villas","source":"https://www.greatbasinpark.com/where-to-stay","accessed":"2026-10-03","si":["family","group"],"booking_route":"phone 435-294-7403","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"Cabins in the Baker area, listed by the Great Basin Business and Tourism Council with contact 435-294-7403."},{"name":"Holiday Inn Express & Suites Ely","source":"https://hotelguides.com/attraction-maps/nevada/map-hotels-near-great-basin-national-park-nv.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":35,"blurb":"Listed by HotelGuides at \"1505 East Aultman Street, Ely, NV 89301\", \"39 miles from Great Basin National Park\". IHG''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"La Quinta Inn & Suites Ely","source":"https://hotelguides.com/attraction-maps/nevada/map-hotels-near-great-basin-national-park-nv.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"brand booking (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":36,"blurb":"Listed by HotelGuides at \"1591 Great Basin Blvd, Ely, NV 89301\", \"39 miles from Great Basin National Park\". Nothing else about the property is stated here."},{"name":"Ramada Inn & Copper Queen Casino Ely","source":"https://hotelguides.com/attraction-maps/nevada/map-hotels-near-great-basin-national-park-nv.html","accessed":"2026-10-03","si":["entertainment","family"],"booking_route":"brand booking (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":37,"blurb":"Listed by HotelGuides at \"805 East 7th Street, Ely, NV 89301\", \"39 miles from Great Basin National Park\". Nothing else about the property is stated here."},{"name":"487 Grill","source":"https://www.greatbasinpark.com/eat-and-drink","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Listed by the Great Basin Business and Tourism Council with the Bristlecone General Store: \"Fridays, Saturdays & Sundays 4PM-8PM\"; the NPS lists it in Baker as \"Open spring through fall\" for \"Lunch and dinner service\"."},{"name":"Sandra''s Mexican Food Truck","source":"https://www.greatbasinpark.com/eat-and-drink","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-up food truck","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"Listed by the Great Basin Business and Tourism Council (facebook.com/SandrasMexicanFoods); the NPS lists Sandra''s Mexican Food in Baker with \"Hours Vary\" and \"Lunch and dinner service\"."},{"name":"Border Inn Casino","source":"https://www.greatbasinpark.com/eat-and-drink","accessed":"2026-10-03","si":["culinary","entertainment","motoring"],"booking_route":"walk-in; motel and RV by phone (775) 234-7300","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","stay"],"draw_rank":40,"blurb":"Restaurant and bar with a convenience store, \"open 24 hours a day for play\" (Great Basin Business and Tourism Council); the NPS lists it 8 miles northeast of Baker with \"Gas, diesel, motel, restaurant, RV campsites\", (775) 234-7300. Its own website refused access from our location."},{"name":"Major''s Station RV Park","source":"https://www.nps.gov/grba/planyourvisit/goodsandservices.htm","accessed":"2026-10-03","si":["motoring"],"booking_route":"phone (775) 591-0347","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":41,"blurb":"Listed by the NPS \"40 miles west toward Ely\" for \"RV and tent camping\", (775) 591-0347. No own website was found or read."}],"faq":[{"q":"Is Great Basin National Park free?","a":"Entry is: \"An entrance pass is not required to access Great Basin National Park.\" Cave tours ($5-$40 for adults) and developed campgrounds ($20 a night) carry their own fees.","source":"https://www.nps.gov/grba/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Great Basin National Park?","a":"Yes. \"Great Basin has five campgrounds available for visitors. Some campgrounds are closed seasonally due to weather.\" There are group sites at Grey Cliffs, free primitive campsites (\"free but do not have water\") and backcountry camping; \"There are many options to camp outside Great Basin National Park when the campgrounds fill.\"","source":"https://www.nps.gov/grba/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Where can you see bristlecone pines in Great Basin National Park?","a":"On the Bristlecone Trail from the Bristlecone Trailhead at the end of the Wheeler Peak Scenic Drive: 2.8 miles round trip, 600 feet of gain from 9,890 feet, rated Moderate, to the Wheeler Peak Bristlecone Grove, home to \"the oldest living organisms in the world.\"","source":"https://www.nps.gov/thingstodo/hike-to-the-wheeler-peak-bristlecone-grove.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Great Basin National Park?","a":"The NPS lists Cedar City Regional Airport at 142 miles, St. George Regional Airport at 207 miles, Salt Lake City at 234 miles and Las Vegas at 286 miles; the full-service airports with \"rental cars, international flights\" are Salt Lake City and Las Vegas.","source":"https://www.nps.gov/grba/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"How far is Great Basin National Park from Las Vegas?","a":"The NPS gives 286 miles from the Las Vegas airport. From southern Nevada: \"Take U.S. Highway 93 north to the junction with Highways 6 & 50\", then south on Nevada 487 five miles to Baker and west on Highway 488 five miles to the park.","source":"https://www.nps.gov/grba/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you bring dogs to Great Basin National Park?","a":"Only in limited places: \"Leashed pets can only be exercised in the campgrounds, in front of the visitor centers, and along roads.\" \"Pets are not permitted on trails or in the backcountry of the park, except leashed pets on the Lexington Arch Trail or the trail between Baker and the Great Basin Visitor Center\", and \"Pets are not permitted in Lehman Caves or at evening programs\".","source":"https://www.nps.gov/grba/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Is Great Basin National Park open in winter?","a":"Yes. \"Lehman Caves Tours are also offered year round\" and \"Lower Lehman Creek Campground remains open through winter.\" \"The Wheeler Peak Scenic Drive closes to vehicle traffic, but remains open to skiers and snowshoers\", and \"no food service exists in the park during the winter.\"","source":"https://www.nps.gov/grba/planyourvisit/visiting-in-winter.htm","accessed":"2026-10-03"},{"q":"Is there cell service in Great Basin National Park?","a":"Not reliably: \"Cell phone reception is not reliable in the park and surrounding areas. Do not rely on them!\"","source":"https://www.nps.gov/grba/planyourvisit/safety.htm","accessed":"2026-10-03"},{"q":"When was Great Basin National Park established?","a":"\"Great Basin National Park - October 27, 1986; Lehman Caves National Monument - January 24, 1922\".","source":"https://www.nps.gov/grba/faqs.htm","accessed":"2026-10-03"},{"q":"What time zone is Great Basin National Park in?","a":"Pacific. Driving in from southern Utah, \"you will be crossing into the Pacific Time zone when you cross the Nevada border.\"","source":"https://www.nps.gov/grba/planyourvisit/directions.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Great Basin National Park: Lehman Caves, Bristlecones & Dark Skies | TravelWell","meta_description":"Free entry, Lehman Caves tours booked 30 days out, the Bristlecone Trail from 9,890 ft, Gold Tier dark skies, and where to camp and stay near Baker, Nevada.","slug":"great-basin-national-park-nevada","primary_keyword":"Great Basin National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Great Basin National Park bristlecone pine Wheeler Peak"}}'::jsonb, 88),
  ('joshua-tree-california', '12A', 'Joshua Tree National Park', 'United States', 'Boulder piles, 8,000 climbing routes, an International Dark Sky Park, and a high-desert ring of Airstreams, saloons and sound baths', 'future', 'verified', 'mountainValley', 'Southern California', '{"adventure","hiking","glamping","wellness","culture","parks"}', '{"rugged","wild","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Hidden Valley Nature Trail","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a 1-mile easy loop from the Hidden Valley picnic area into \"a rock-enclosed valley that was once rumored to have been used by cattle rustlers\"; its lot is one the NPS says may close temporarily at capacity"},{"name":"Keys View","source":"https://www.nps.gov/jotr/planyourvisit/placestogo.htm","accessed":"2026-10-02","si":["senior","family","romance"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"\"panoramic views of the Coachella Valley, the San Andreas Fault, and the high peaks of San Jacinto and San Gorgonio\"; a 0.25-mile short, paved, steep loop that also takes in the Salton Sea"},{"name":"Cholla Cactus Garden","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a 0.25-mile easy loop through \"thousands of densely concentrated, naturally growing cholla cactus\", 20 miles north of Cottonwood Visitor Center; the NPS page still carries a note that it was \"Closed December 2024-March 2025 for maintenance\""},{"name":"Skull Rock","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a 1.7-mile easy loop from the parking area just east of Jumbo Rocks Campground through boulder piles and desert washes to \"the namesake Skull Rock\""},{"name":"Barker Dam","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["wildlife","family","hiking"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a 1.1-mile easy loop to a water tank built by early cattle ranchers - \"Watch for bighorn sheep\"; another lot that may close at capacity"},{"name":"Ryan Mountain","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a strenuous 3-mile out-and-back with 1,050 feet of climb to the summit - \"one of the most popular hikes in the park\""},{"name":"Lost Palms Oasis and Cottonwood Spring","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","expedition","wildlife"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a strenuous 7.5-mile out-and-back from Cottonwood Spring, seven miles inside the South Entrance, down into a canyon to \"a remote fan palm oasis\"; Cottonwood Spring offers cultural history, birding and hiking"},{"name":"Rock climbing and bouldering","source":"https://www.nps.gov/jotr/planyourvisit/climbing.htm","accessed":"2026-10-02","si":["adventure","sports"],"booking_route":"not applicable - guided climbing via permitted guides","tier_absent_reason":"not-sold","blurb":"\"more than 8,000 climbing routes, 2,000 boulder problems\"; a permit is required for any placement, replacement or removal of fixed anchors, and commercial guides must be permitted and hold PCGI, AMGA or similar certification"},{"name":"International Dark Sky Park stargazing","source":"https://www.nps.gov/jotr/planyourvisit/stargazing.htm","accessed":"2026-10-02","si":["romance","family","wellness"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"four designated stargazing areas at Quail Springs, Hidden Valley, Cap Rock and Ryan Mountain parking lots; for darker skies the NPS names Cottonwood Campground and Pinto Basin Road between Cholla Cactus Garden and Cottonwood"},{"name":"Keys Ranch tours","source":"https://www.nps.gov/jotr/planyourvisit/fees.htm","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"advance reservation required (booking platform not confirmed this session)","tier_absent_reason":"not-sold","blurb":"a guided tour of the historic ranch, listed by the NPS at \"$10-20 per visitor\" with advance reservations required"},{"name":"Geology Tour Road","source":"https://www.nps.gov/jotr/planyourvisit/backcountry-roads.htm","accessed":"2026-10-02","si":["adventure","expedition"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"5.4 miles to Paac Kü̱vü̱hü̱''k plus a 6-mile loop; \"High Clearance and 4-Wheel-Drive Required\" - one of four NPS backcountry roads with Berdoo Canyon, Old Dale and Pinkham/Thermal Canyon"},{"name":"Fortynine Palms Oasis","source":"https://www.nps.gov/jotr/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking","wildlife"],"booking_route":"not applicable - no booking","tier_absent_reason":"not-sold","blurb":"a 3-mile out-and-back off Highway 62 over a ridge of barrel cactus to a fan palm oasis; the NPS marks it strenuous and says \"Avoid this trail when it''s hot out\""},{"name":"AutoCamp Joshua Tree","source":"https://autocamp.com/location/joshua-tree/","accessed":"2026-10-02","si":["glamping","family","romance"],"booking_route":"own booking widget on autocamp.com (engine not named)","tier_absent_reason":"not-sold","blurb":"31-foot Airstreams and Classic and Premium Cabins at 62209 Verbena Road, Joshua Tree; Vista units with