insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('channel-islands-california', '12A', 'Channel Islands National Park', 'United States', 'Five wild islands off the Ventura coast', 'future', 'verified', 'mountainValley', 'Southern California', '{"hiking","wildlife","ocean","adventure","family","parks"}', '{"wild","remote","coastal","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Island Packers ferry to the five islands","source":"https://islandpackers.com/information/faq/","accessed":"2026-10-03","si":["ocean","wildlife","family","group","senior"],"booking_route":"own website booking (islandpackers.com/book/) or (805) 642-1393","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move","activities"],"draw_rank":1,"blurb":"The park''s boat concessioner: \"Boat Transportation to Channel Islands National Park, Island Trips, Wildlife Cruises, Camping & More\" - day landing trips to all five islands from Ventura Harbor (1691 Spinnaker Dr.) and Channel Islands Harbor, Oxnard. Crossing times: \"Anacapa & Santa Cruz: About 1 hour / Santa Rosa & Santa Barbara: About 2.5-3.5 hours / San Miguel: About 3-4.5 hours\". (805) 642-1393."},{"name":"Cavern Point Loop, Santa Cruz Island","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03","si":["hiking","wildlife","family"],"booking_route":"none needed - free park trail; reached by Island Packers boat","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"2 miles round trip, MODERATE, from Scorpion Beach: \"Not to be missed. Magnificent coastal vistas and seasonal whale viewing. To avoid a steep climb, hike clockwise, beginning from campground (near site #22) and looping back to Scorpion Anchorage.\""},{"name":"Painted Cave, Santa Cruz Island","source":"https://www.nps.gov/chis/planyourvisit/santa-cruz-island.htm","accessed":"2026-10-03","si":["ocean","adventure"],"booking_route":"none needed - seen from the water; no landing","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"NPS: \"one of the largest and deepest sea caves in the world\", on the northwest coastline of Santa Cruz."},{"name":"Whale watching in the Santa Barbara Channel","source":"https://www.nps.gov/chis/planyourvisit/whale-watching.htm","accessed":"2026-10-03","si":["wildlife","ocean","family","senior"],"booking_route":"from shore free; by boat with Island Packers (\"offers whale watching during the year\")","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Over 30 different marine mammal species can be found in the park\"; \"The most common sightings are of gray whales from mid- to late-December through mid-March, blue and humpback whales during the summer, and common dolphins throughout the entire year.\" \"The park visitor center has a tower with telescopes, which can be used for whale watching.\""},{"name":"Anacapa Island and its 1932 light station","source":"https://www.nps.gov/chis/planyourvisit/anacapa.htm","accessed":"2026-10-03","si":["wildlife","hiking","culture"],"booking_route":"none needed in the park; boat via Island Packers","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Almost five miles long, these islets (appropriately named East, Middle, and West Anacapa Islands) are inaccessible from each other except by boat\"; \"the largest breeding colony of western gulls in the world\"; \"Visitors can view the 1932 light station whose mission revival style buildings include the lighthouse, fog signal building, one of four original keeper''s quarters\"."},{"name":"Robert J. Lagomarsino Visitor Center, Ventura Harbor","source":"https://www.nps.gov/chis/planyourvisit/visitorcenters.htm","accessed":"2026-10-03","si":["family","senior","wildlife"],"booking_route":"none needed - free; (805) 658-5730","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"1901 Spinnaker Drive, Ventura: \"The fully accessible visitor center is open 8:30 am until 5 pm daily\"; \"a bookstore, a display of marine aquatic life, and exhibits featuring the unique character of each park island\"; the 25-minute film \"A Treasure in the Sea\" when available; \"On weekends and holidays at 11 am and 3 pm rangers offer a variety of free public programs\". Closed Thanksgiving and December 25."},{"name":"Channel Islands Junior Ranger badge","source":"https://www.nps.gov/chis/learn/kidsyouth/junior-ranger.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - free booklet","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Complete a Channel Islands Junior Ranger Booklet and earn a free badge.\" \"Bring your completed booklet to the visitor center in Ventura Harbor or park staff on the islands to get your badge. Booklets are also available at the visitor center, on the islands from park staff, and at Island Packers.\""},{"name":"Scorpion Canyon Campground, Santa Cruz Island","source":"https://www.nps.gov/chis/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","group","family","adventure"],"booking_route":"Recreation.gov, up to six months ahead; boat booked separately with Island Packers","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"\"25 sites plus 6 group sites\", half a mile from the pier, vault toilets, drinking water available; the NPS calls it \"the most convenient park campground and provides the most recreational opportunities.\" \"Reservations are required for all park campgrounds\" and \"can be made up to six months in advance on recreation.gov.\""},{"name":"Potato Harbor overlook, Santa Cruz Island","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03","si":["hiking"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"5 miles round trip, MODERATE: \"A longer hike than the Cavern Point hike, but also with spectacular coastal views. No beach access.\" Reached by the North Bluff Trail from Cavern Point."},{"name":"Point Bennett, San Miguel Island","source":"https://www.nps.gov/chis/planyourvisit/san-miguel-island.htm","accessed":"2026-10-03","si":["wildlife","hiking","adventure"],"booking_route":"ranger-guided hike; boat via Island Packers (3-4.5 hours)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"over 30,000 pinnipeds and up to five different species hauled out on the point''s beaches at certain times of year\", reached on an \"all-day, ranger-guided, 16-mile round-trip hike across the island\"; a memorial to Cabrillo stands \"on a bluff overlooking Cuyler Harbor\"."},{"name":"Santa Rosa Island Torrey pines","source":"https://www.nps.gov/chis/planyourvisit/santa-rosa-island.htm","accessed":"2026-10-03","si":["hiking","culture","wildlife"],"booking_route":"none needed in the park; boat via Island Packers (2.5-3.5 hours)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"An island of \"approximately 53,000 acres\" whose Torrey pine subspecies \"is considered one of the rarest pines in the world\"; \"Home to the Island Chumash until approximately 1820, Wima (as the Chumash refer to the island)\"; the \"buildings and equipment of the historic Vail and Vickers ranch at Bechers Bay\"."},{"name":"Scorpion Canyon Loop and the island scrub-jay","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"4.5 miles round trip, MODERATE TO STRENUOUS: \"A scenic loop hike to the interior with a chance to see the unique island scrub-jay.\" The NPS lists Santa Cruz''s \"eight plant species found only on Santa Cruz and nowhere else in the world\"."},{"name":"Smugglers Cove, Santa Cruz Island","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"7.5 miles round trip, STRENUOUS: \"Follow the Smugglers Road to the beach at Smugglers Cove. Carry water. No water available at Smugglers.\""},{"name":"Historic Scorpion Ranch","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"0.5 miles round trip, EASY: \"View the historic Scorpion Ranch complex dating to the late 1800s. Exhibit areas include an orientation kiosk, blacksmith shop, farm implements, and a visitor center located in the Scorpion ranch house.\""},{"name":"The island campgrounds of Anacapa, Santa Rosa, San Miguel and Santa Barbara","source":"https://www.nps.gov/chis/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov, up to six months ahead","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"Anacapa: 7 sites, half a mile from the pier \"(includes 157 stairs)\", no drinking water; Santa Rosa''s Water Canyon: 15 sites, flush toilets, drinking water; San Miguel: 9 sites, \"1 mile on steep/narrow trail\"; Santa Barbara: 10 sites; Prisoners Harbor on Santa Cruz: 6 sites. \"Campfires are not allowed.\""},{"name":"Water, food and layers for a day on the islands","source":"https://www.nps.gov/chis/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"NPS: \"There are no supplies on the islands. Take water, food, and other necessities.\" \"Weather conditions change rapidly; dress in layers.\" Island Packers adds a jacket, closed-toe shoes, sunscreen and a hat to the list."},{"name":"Wind-proof tent and stove for island camping","source":"https://www.nps.gov/chis/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to campsaver.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"NPS camping rules: sturdy, low-profile tents with stakes for the wind, \"especially outer islands\"; \"Campfires are not allowed. Use only chemical-fuel stoves for cooking\"; \"Campers must store all food and trash in animal-proof containers. Food storage boxes are provided at campsites\"; \"Campers must pack out their own trash.\""},{"name":"Sea kayak safety kit: lifejacket, helmet, wetsuit","source":"https://www.nps.gov/chis/planyourvisit/kayaking.htm","accessed":"2026-10-03","si":["adventure","ocean"],"booking_route":"affiliate referral to rei.com (AvantLink); boats and wetsuits are included on the concessioner''s guided tours","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"NPS: \"Lifejackets-all paddlers must have lifejackets\"; visitors must \"wear a helmet at all times when exploring sea caves\"; \"Wetsuits are highly recommended. Water temperatures remain cold throughout the year.\" Paddlers also carry a VHF radio, tow line, compass, throw bag, first aid kit and signalling device."},{"name":"Channel Islands Adventure Company","source":"https://www.islandkayaking.com/","accessed":"2026-10-03","si":["adventure","ocean","group","family"],"booking_route":"ZAUI online booking (sbadventureco.zaui.net) from the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":19,"blurb":"\"Authorized Concessioner in Channel Islands National Park\" since 1999: \"Channel Islands Sea Cave Kayak Tours\" and guided snorkelling; \"Ocean kayaks, paddle jackets, helmets, wet suits, and basic kayaking instruction are included.\" Snorkel tour \"Ages 10+\" and guests \"must know how to swim\". Has \"led hundreds of schools groups on outdoor education trips since 1999.\" The NPS names it as the guided kayak concessioner at Scorpion Anchorage, with \"snorkel equipment rentals\". (805) 884-9283."},{"name":"Channel Islands Kayak Center","source":"https://www.cikayak.com/","accessed":"2026-10-03","si":["adventure","ocean","family"],"booking_route":"own website tours page or phone","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":20,"blurb":"\"local kayak and stand up paddleboard rentals, our family friendly History and Wildlife kayak adventure tour, as well servicing rentals and guided kayak tours to the world famous Channel Islands\"; sells the Hobie kayak line with \"free demo''s daily\". Channel Islands Harbor (3600 S. Harbor Blvd.) and Ventura (1691 Spinnaker Drive). Island Packers: \"Rentals are available through Channel Islands Kayak Center.\" (805) 984-5995."},{"name":"Ventura Dive & Sport","source":"http://venturadive.com/","accessed":"2026-10-03","si":["diveglobal","ocean","family"],"booking_route":"charter portal from the own website; phone","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":21,"blurb":"1559 Spinnaker Dr, Suite 108, Ventura: a 5-Star PADI Instructor Development Center with \"Rental Equipment\", PADI courses including SCUBA Camp (ages 10-15), and the dive boat Raptor (\"Fast, comfortable and spacious\") running trips to Anacapa and Santa Cruz. 1-805-650-6500."},{"name":"Ventura Beach RV Resort","source":"https://www.vbrvresort.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone only (805-643-9137)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"800 West Main Street, Ventura, on 14 acres: RV sites, tent camping and rentals; \"Swimming pool and hot tub, restrooms and showers, laundry facilities, free Wi-Fi, a recreation room, playground, general store\"; \"Just a short 7-minute walk from the beach and minutes from Ventura Pier and Downtown Ventura.\" \"NO ONLINE RESERVATIONS! PLEASE CALL 805-643-9137\"."},{"name":"Rincon RV Parkway","source":"https://visitventuraca.com/camping/","accessed":"2026-10-03","si":["motoring","ocean"],"booking_route":"none - first come, first served (Ventura County Parks)","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"Pacific Coast Highway, 6 miles north of Ventura: \"Close to 130 sites\" for self-contained RVs only; \"No hook-ups. First come, first served only. 5 day stay limit April 1- October 31; 14 day limit November 1 - March 31.\""},{"name":"Faria County Campground","source":"https://visitventuraca.com/camping/","accessed":"2026-10-03","si":["family","motoring","ocean"],"booking_route":"Ventura County Parks, ventura.org/parks-department or 805-654-5000","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"4350 West Pacific Coast Highway, 5 miles north of Ventura: \"42 sites for tents and RVs. Full hook-ups, showers, fire rings, playground, horseshoe pits.\" Booked through Ventura County Parks (ventura.org/parks-department or 805-654-5000)."},{"name":"Emma Wood State Beach and Ventura River Group Camp","source":"https://www.parks.ca.gov/?page_id=604","accessed":"2026-10-03","si":["group","ocean","motoring"],"booking_route":"ReserveCalifornia","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"\"The beach is two miles west of Ventura.\" \"There are 90 campsites\" for self-contained vehicles only, \"Tents are not permitted\"; the Ventura River Group Camp has \"four developed group campsites, each with a capacity of 30 people\" plus a primitive RV area \"for groups up to 50 people\". California State Parks notes North Beach \"closed through at least June 2026 due to construction projects\"."},{"name":"Waypoint Ventura vintage trailers","source":"http://waypointventura.com/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"own website booking (ResNexus)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"398 S Ash St. Unit E, Ventura: \"a unique outdoor experience from the comfort of luxuriously restored vintage trailers both close to historic downtown, and near the beach\"; \"Bikes, Cornhole, BBQs & More\". Visit Ventura lists \"overnight stay in a vintage Gulfstream\" with \"complimentary beach cruisers and s''mores\"."},{"name":"Four Points by Sheraton Ventura Harbor Resort","source":"https://visitventuraca.com/business/four-points-by-sheraton-ventura-harbor-resort/","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":27,"blurb":"1050 Schooner Dr, Ventura: \"With easy access to downtown Ventura, Ventura Harbor and Oxnard, Four Points is the perfect home base for your next Ventura County adventure!\" Outdoor heated pool, bicycle rentals, Alexander''s Restaurant; the listing notes proximity to Channel Islands National Park. (805) 658-1212."},{"name":"Ventura Beach Marriott","source":"https://visitventuraca.com/business/ventura-beach-marriott/","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":28,"blurb":"2055 E. Harbor Blvd., Ventura: \"only two blocks from the ocean\" on \"a 10-mile stretch of the sparkling Pacific coast between Los Angeles and Santa Barbara\"; 285 guest rooms and 16 suites, heated outdoor pool, 12 meeting rooms, pet- and bike-friendly. (805) 643-6000."},{"name":"Crowne Plaza Ventura Beach","source":"https://visitventuraca.com/business/crowne-plaza-ventura-beach-2/","accessed":"2026-10-03","si":["group","family","senior","romance"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":29,"blurb":"450 E Harbor Blvd, Ventura: \"258 ocean view guest rooms, all with private balconies\" and \"16 deluxe ocean view suites\", a heated beachfront pool and 11 meeting rooms including two ballrooms. (805) 648-2100."},{"name":"Residence Inn by Marriott Ventura Beach","source":"https://visitventuraca.com/business/residence-inn-by-marriott-ventura-beach/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":30,"blurb":"788 S Seaward Ave, Ventura: \"Spacious suites with kitchens and living areas, complimentary breakfast, a heated outdoor pool, and fitness facilities make this hotel ideal for beach getaways and extended stays.\" (805) 618-2500."},{"name":"Ventura Harbor Village","source":"https://www.venturaharborvillage.com/","accessed":"2026-10-03","si":["family","culinary","senior"],"booking_route":"none needed - a public harbour village","commission_status":"none","tier_absent_reason":"not-sold","wells":["shop","eat"],"draw_rank":31,"blurb":"1583 Spinnaker Drive, Ventura - the harbourside shopping and dining village on the same street as the NPS visitor center (1901 Spinnaker) and Island Packers (1691 Spinnaker); October 2026 events listed include an NSSA Surf Competition and live music."},{"name":"Outdoors Santa Barbara Visitor Center","source":"https://www.nps.gov/chis/planyourvisit/visitorcenters.htm","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":32,"blurb":"113 Harbor Way, 4th Floor, Santa Barbara: \"Open 10:30 am until 4:30 pm daily\", closed Thanksgiving Day, December 25, January 1 and the first Friday in August for Fiesta; information on Channel Islands National Park. (805) 884-1475."},{"name":"Andria''s Seafood Restaurant & Market","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method on the listing read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Ventura Harbor, since 1982: \"seafood right off the boat\", with clam chowder made from scratch daily and served in sourdough bread bowls, and an attached seafood market (Visit Ventura)."},{"name":"Brophy Bros. Ventura Harbor","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary"],"booking_route":"not stated on the listing read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"Ventura Harbor seafood with harbour views; the fish stew cioppino is featured (Visit Ventura)."},{"name":"Lure Fish House","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"not stated on the listing read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"Downtown Ventura seafood restaurant known for clam chowder, oysters and wild mahi-mahi (Visit Ventura)."},{"name":"Spencer Makenzie''s Fish Co.","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method on the listing read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Downtown Ventura: \"a more casual alternative\" for seafood that \"serves some of the best fish tacos\" (Visit Ventura)."},{"name":"The Jolly Oyster","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary","ocean"],"booking_route":"walk-up","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"A trailer at San Buenaventura State Beach selling fresh, sustainably grown oysters and clams (Visit Ventura)."},{"name":"Paradise Pantry","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["wine","culinary","romance"],"booking_route":"not stated on the listing read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Downtown Ventura: \"a restaurant, market, and wine bar in one\" - cheese plates, pates, salads, soups and paninis (Visit Ventura)."},{"name":"Beach House Fish and the MadeWest tap room","source":"https://visitventuraca.com/restaurants/","accessed":"2026-10-03","si":["culinary","ocean"],"booking_route":"not stated on the listing read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"On the Ventura pier: drinks, eats and Pacific views, with the MadeWest Brewing Company tap room on the second floor (Visit Ventura)."}],"faq":[{"q":"Can you drive to Channel Islands National Park?","a":"Not to the islands. The NPS says \"you can''t drive to the islands. A short but exciting ocean voyage or a commercial flight in a small airplane is required.\" You can drive to the mainland visitor center in Ventura Harbor, \"the only location visitable in under half a day without island travel.\"","source":"https://www.nps.gov/chis/planyourvisit/index.htm","accessed":"2026-10-03"},{"q":"How do I get to Channel Islands National Park from Ventura?","a":"By boat. \"Islands can only be reached by boat. Advanced planning is highly recommended.\" Island Packers, \"1691 Spinnaker Dr. Ventura, CA 93001\", (805) 642-1393, runs the public boat service from Ventura Harbor and Channel Islands Harbor.","source":"https://www.nps.gov/chis/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"How long is the ferry ride to Channel Islands National Park?","a":"Island Packers: \"Travel times vary by island, route, weather, and wildlife sightings: Anacapa & Santa Cruz: About 1 hour / Santa Rosa & Santa Barbara: About 2.5-3.5 hours / San Miguel: About 3-4.5 hours\".","source":"https://islandpackers.com/information/faq/","accessed":"2026-10-03"},{"q":"Can you camp at Channel Islands National Park?","a":"Yes, on all five islands. \"Reservations are required for all park campgrounds\" and \"can be made up to six months in advance on recreation.gov.\" Scorpion Canyon on Santa Cruz has \"25 sites plus 6 group sites\" and drinking water; on most islands \"Drinking water...must be brought with you\". \"Campfires are not allowed.\"","source":"https://www.nps.gov/chis/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"How much does Channel Islands National Park cost?","a":"Entry is free: \"An entrance pass is not required to access Channel Islands National Park.\" Camping and the boat crossing are paid separately; those fares were not on the pages read.","source":"https://www.nps.gov/chis/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Channel Islands National Park?","a":"The NPS says \"The best chance for warm weather, calm winds, and seas continues\" through the fall, particularly October. \"Dense fog is common during the late spring and early summer months\", and \"most rain falling between December and March.\" Gray whales pass \"from mid- to late-December through mid-March\".","source":"https://www.nps.gov/chis/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Is Channel Islands National Park dog friendly?","a":"No. \"No pets. Pets are not allowed on the islands. Pets can carry diseases that could harm the island fox or other animals that are unique to the islands. Service animals require a permit from the park superintendent.\"","source":"https://www.nps.gov/chis/planyourvisit/upload/sci-hiking-2022-ADA.pdf","accessed":"2026-10-03"},{"q":"Can you snorkel at Channel Islands National Park?","a":"Yes: \"Cool off after a hike with a snorkel, dive, or kayak in the Landing Cove on Anacapa Island or at Scorpion Anchorage on Santa Cruz Island.\" The park''s kayak concessioner, Channel Islands Adventure Company, offers \"snorkel equipment rentals, and guided snorkel tours\"; \"Wetsuits are highly recommended. Water temperatures remain cold throughout the year.\"","source":"https://www.nps.gov/chis/planyourvisit/kayaking.htm","accessed":"2026-10-03"},{"q":"Does Channel Islands National Park have a visitor center?","a":"Yes, on the mainland at 1901 Spinnaker Drive, Ventura: \"The fully accessible visitor center is open 8:30 am until 5 pm daily\", with free ranger programmes \"On weekends and holidays at 11 am and 3 pm\". A second contact station, Outdoors Santa Barbara, is at 113 Harbor Way, Santa Barbara.","source":"https://www.nps.gov/chis/planyourvisit/visitorcenters.htm","accessed":"2026-10-03"},{"q":"Is Channel Islands National Park good for kids?","a":"The park runs a Junior Ranger programme: \"Complete a Channel Islands Junior Ranger Booklet and earn a free badge.\" \"Booklets are also available at the visitor center, on the islands from park staff, and at Island Packers.\"","source":"https://www.nps.gov/chis/learn/kidsyouth/junior-ranger.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Channel Islands National Park: Ferry, Camping & Sea Caves | TravelWell","meta_description":"Free entry, boats from Ventura in about an hour, island camping booked six months ahead, sea cave kayaking, whales by season, and where to stay in Ventura.","slug":"channel-islands-national-park-california","primary_keyword":"Channel Islands National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Channel Islands National Park Santa Cruz Island"}}'::jsonb, 90),
  ('yosemite-california', '12A', 'Yosemite National Park', 'United States', 'A granite valley with a 2,425-foot waterfall, a cable route up Half Dome, and a ring of glamping camps on three highways', 'future', 'verified', 'mountainValley', 'Central Coast & the Sierra', '{"hiking","glamping","adventure","family","parks"}', '{"dramatic","alpine","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Yosemite Valley","source":"https://www.nps.gov/yose/planyourvisit/yv.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"El Capitan rising over 3,000 feet, Half Dome and the spring waterfalls; open year-round by Highways 41, 140 and 120, with a free valley shuttle"},{"name":"Yosemite Falls","source":"https://www.nps.gov/yose/planyourvisit/waterfalls.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"2,425 feet, the tallest fall the NPS lists in the park, peaking in May"},{"name":"The Mist Trail to Vernal and Nevada Falls","source":"https://www.nps.gov/yose/planyourvisit/vernalnevadatrail.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"from Happy Isles: 2.4 mi round trip and 1,000 ft to the top of Vernal Fall, 5.4 mi and 2,000 ft to the top of Nevada Fall"},{"name":"Half Dome cables (permit required)","source":"https://www.nps.gov/yose/planyourvisit/hdpermits.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"permit required seven days a week while cables are up; 300 hikers a day; preseason lottery March 1-31, $10 application plus $10 per person if awarded"},{"name":"Glacier Point","source":"https://www.nps.gov/yose/planyourvisit/glacierpoint.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"3,214 feet above Curry Village, looking across Yosemite Valley, Half Dome, Yosemite Falls and the high country; about an hour''s drive from the valley"},{"name":"Mariposa Grove of Giant Sequoias","source":"https://www.nps.gov/yose/planyourvisit/mg.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"over 500 mature giant sequoias including the roughly 3,000-year-old Grizzly Giant; protected by Lincoln in 1864; free shuttle mid-April to November"},{"name":"Tioga Road","source":"https://www.nps.gov/yose/learn/news/yosemite-national-park-announces-summer-reopenings-full-campground-access-and-early-tioga-road-opening.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"the seasonal high-country road; NPS says its opening cannot be predicted, and in 2026 it opened May 15, the earliest in 16 years"},{"name":"Hetch Hetchy and Wapama Falls","source":"https://www.nps.gov/yose/planyourvisit/hetchhetchy.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"at 3,900 ft with one of the longest hiking seasons in the park; a 5-mile round trip across the dam and through the tunnel to Tueeulala and Wapama falls"},{"name":"Horsetail Fall, mid- to late February","source":"https://www.nps.gov/yose/planyourvisit/horsetailfall.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"a 1,000-ft fall that can glow orange when backlit by sunset; no reservation required in February 2026, with road and parking restrictions in place"},{"name":"Yosemite Valley campgrounds: Upper, Lower and North Pines","source":"https://www.nps.gov/yose/planyourvisit/campground.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"NPS campgrounds, reservations required; Upper Pines open all year, Lower Pines Apr 21-Oct 19, North Pines Apr 21-Oct 26; booked 5 months ahead on the 15th (North Pines also by lottery)"},{"name":"Camp 4","source":"https://www.nps.gov/yose/planyourvisit/campground.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Yosemite Valley campground open all year; reservations required, released 1 week ahead for Apr 15-Nov 29"},{"name":"Wawona and Hodgdon Meadow campgrounds","source":"https://www.nps.gov/yose/planyourvisit/campground.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"two all-year NPS campgrounds south and north of the valley; reservations required, released 5 months ahead on the 15th for the main season"},{"name":"Tioga Road and high-country campgrounds","source":"https://www.nps.gov/yose/planyourvisit/campground.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Tuolumne Meadows (Jul 1-Sep 27; 2 months ahead on the 15th and 14 days ahead), plus Crane Flat, Tamarack Flat, White Wolf, Yosemite Creek and Porcupine Flat (2 weeks ahead); all reservation-required; 2026 front-country campgrounds bookable on Recreation.gov"},{"name":"Curry Village tent cabins","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"wood-framed canvas tent cabins with wood floors and electric lighting in Yosemite Valley, alongside hard-sided cabins; seasonal, booked through Yosemite Hospitality"},{"name":"High Sierra Camps","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"fully outfitted shared tent cabins at five wilderness camps - Glen Aulin, May Lake, Sunrise, Merced Lake and Vogelsang - reserved by lottery"},{"name":"Under Canvas Yosemite, Groveland","source":"https://www.undercanvas.com/camps/yosemite/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"71 safari-style tents with ensuite baths on 85 acres, 10 minutes from the Big Oak Flat entrance, on-site YARTS stop; 2026 season April 16 - October 26, 2027 April 15 - October 25"},{"name":"AutoCamp Yosemite, Midpines","source":"https://autocamp.com/yosemite/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"31-foot Airstream suites, Airstream-plus-canvas BaseCamps, Adventure Tents and cabins at 6323 CA-140, with clubhouse and pool"},{"name":"Wildhaven Yosemite Glamping, Mariposa","source":"https://www.wildhavenyosemite.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"heated canvas glamping tents and tiny-home cabins at 4808 Highway 140, 45 minutes to the Arch Rock entrance, with heated pool and fire pits"},{"name":"Indian Flat RV Campground, El Portal","source":"https://www.yosemite.com/places-to-stay/camping-and-rv/indian-flat-rv-campground/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"Jupe glamping tents with 12-foot ceilings, queen beds and air conditioning, plus cabins, RV and tent sites at 9988 Highway 140; described as the closest campsite to the Arch Rock entrance"},{"name":"Yosemite Bug Rustic Mountain Resort, Midpines","source":"https://www.yosemite.com/places-to-stay/hotels-and-motels/yosemite-bug-rustic-mountain-resort/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"insulated tent cabins, hostel dorms, private rooms and cabins 26 miles from Yosemite Valley on Highway 140, with cafe, hot tub, sauna and a nearby YARTS stop"},{"name":"Evergreen Lodge glamping, Groveland","source":"https://www.evergreenlodge.com/stay/resort-glamping/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"Couples and Family tents just outside the Big Oak Flat entrance at 33160 Evergreen Road, spring through fall, with access to the resort''s pool, tavern and daily activities"},{"name":"Yosemite Pines RV Resort & Family Lodging, Groveland","source":"https://www.visittuolumne.com/m/yosemite-pines-rv-resort-family-lodging","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"Conestoga covered wagons sleeping up to 6, 1950s-60s retro trailers, yurts, cabins and full-hookup RV sites 22 miles from the western gate, with pool and petting farm"},{"name":"Outdoorsy Yosemite, Bass Lake","source":"https://yosemite.outdoorsy.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"safari-style glamping tents with private bathrooms, a 2020 Flying Cloud Airstream suite, log cabins and 170 RV sites, 18 miles from the south entrance; open year-round"},{"name":"Tenaya Lodge Explorer Cabins, Fish Camp","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"two-bedroom Explorer Cabins at Tenaya Lodge near the south entrance"},{"name":"Mariposa Fairgrounds RV Park & Campground","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"tent cabins available year-round at the fairgrounds in Mariposa"},{"name":"Lake McSwain Park Cabins","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"six lakefront cabins with bathrooms, showers and kitchens at Lake McSwain Camping & Recreation Area in Mariposa County"},{"name":"Nolla A-Frames Near Yosemite, Groveland","source":"https://www.hipcamp.com/en-US/national-park/united-states/california/yosemite/glamping","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"off-grid, solar-powered Finnish-designed A-frame cabins, listed on Hipcamp"},{"name":"Wondernut Farm, Groveland area","source":"https://www.hipcamp.com/en-US/national-park/united-states/california/yosemite/glamping","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"off-grid working farmstead with a suspended ''hoverbed'' treehouse and cabin lodging, listed on Hipcamp"},{"name":"Heart Valley Ranch, Coulterville area","source":"https://www.hipcamp.com/en-US/national-park/united-states/california/yosemite/glamping","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"a handcrafted Kazakh yurt on 300+ acres with creek access and animal encounters, listed on Hipcamp"},{"name":"Thousand Trails Yosemite Lakes, Groveland","source":"https://thousandtrails.com/california/yosemite-lakes-rv-resort","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"year-round 460-site RV resort on Hardin Flat Road, about 15 minutes from the park entrance, with rental accommodations and tent sites"},{"name":"Yosemite RV Resort, Coarsegold","source":"https://rvcoutdoors.com/yosemite-rv-resort/location/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"RVC Outdoor Destinations park at 34094 Highway 41, 25 miles from the south entrance, with RV sites, cabins, cottages, yurts and tent camping"},{"name":"Rush Creek Lodge and Spa, Groveland","source":"https://www.visittuolumne.com/m/rush-creek-lodge-and-spa","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"143 rooms, suites and hillside villas half a mile from the Highway 120 entrance, with saltwater pool, spa and recreation guide service"},{"name":"The Ahwahnee and the Bracebridge Dinner","source":"https://www.travelyosemite.com/things-to-do/specialty-events/food-and-wine-events/bracebridge-dinner","accessed":"2026-10-02","si":["romance"],"tier_absent_reason":"not-sold","blurb":"the park''s year-round luxury hotel; its dining room stages the Bracebridge Dinner on December 8, 10, 12, 14, 16, 18, 20 and 22, 2026"},{"name":"Yosemite Mountaineering School & Guide Service","source":"https://www.yosemite.com/things-to-do/adventure-activities/yosemite-mountaineering-school-guide-service/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"based at Curry Village since the late 1960s: climbing classes (six students per instructor), private climbs, guided hikes, backpacking, snowshoeing; reservations required"},{"name":"Zephyr Whitewater Expeditions, Merced River","source":"https://zrafting.com/rivers/merced/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Class 3-4 Merced trips from its Midpines property on Highway 140: half-day 11 miles or full-day 16 miles with riverside lunch; described as the largest outfitter on the Merced"},{"name":"Sierra Mac River Trips, Groveland","source":"https://www.sierramac.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"family-owned since 1965, 15 miles outside the northwest entrance: Main Tuolumne 1-3 days (Class IV-V), Merced half and full day (III-IV), and Class V Cherry Creek"},{"name":"Yosemite Trails Horseback Adventures, Fish Camp","source":"https://www.yosemitetrails.com/about_us.html","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"family-run pack station near the south gate, operated by the Knapp family since 1966; spring-to-autumn trail rides on its own American Quarter Horses"},{"name":"Yosemite Valley bike rentals","source":"https://www.travelyosemite.com/things-to-do/biking","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Travel Yosemite stands at Yosemite Valley Lodge, Curry Village and Yosemite Village, April to late October; 12 miles of flat bike paths; $48 full day, $36.50 half day"},{"name":"Ansel Adams Gallery Photography Walk","source":"https://www.nps.gov/planyourvisit/event-details.htm?id=A7C21F2A-B722-C1B2-08FF63BAB1B65612","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"free 90-minute walk with a staff photographer, Tuesdays and Thursdays at 9 a.m. from the gallery in Yosemite Village; registration required; listed through December 31, 2026"},{"name":"Yosemite Conservancy guided adventures","source":"https://yosemite.org/experience/outdoor-adventures/","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"naturalist-led custom, group, birding, art and winter programs that fund the park; next listed: ''Day Hike: Fall Splendor'' in Yosemite Valley on 29 October 2026"},{"name":"Yosemite Mountain Sugar Pine Railroad, Fish Camp","source":"https://www.ymsprr.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"narrow-gauge steam train through Sierra National Forest, 10 minutes from the South Entrance, open April through December, wheelchair accessible"},{"name":"The Local Grape, Mariposa","source":"https://www.yosemite.com/things-to-do/leisure-activities/the-local-grape/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"wine bar and bottle shop on Highway 140 pouring Sierra Foothills AVA wines and acting as a central tasting room for Mariposa County wineries"},{"name":"Iron Door Saloon, Groveland","source":"https://en.wikipedia.org/wiki/Iron_Door_Saloon","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"a pre-1852 granite building on Main Street, a saloon since 1896, whose proprietors call it the oldest continuously operating saloon in California"},{"name":"Mariposa, the Highway 140 gateway","source":"https://www.yosemite.com/yosemite-mariposa-county-region/central-mariposa-county/mariposa-ca/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Gold Rush town settled 1849, 32 miles from the park, with the 1854 courthouse, the Mariposa Museum and History Center and the State Mining and Mineral Museum"},{"name":"Oakhurst and the Highway 41 south gate","source":"https://www.myyosemitepark.com/road-trips/gateway-towns/madera-county/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"about 16 miles south of the South Entrance, the road to Mariposa Grove, Wawona and Glacier Point Road; Bass Lake nearby"},{"name":"Erna''s Elderberry House at Chateau du Sureau, Oakhurst","source":"https://chateausureau.com/","accessed":"2026-10-02","si":["culinary","romance","wine","senior"],"booking_route":"OpenTable, or phone (559) 683-6800","tier_absent_reason":"not-sold","blurb":"Fine-dining room at Chateau du Sureau, a culinary destination for more than 30 years, serving a three- or four-course tasting menu sourced from local farms, with wine pairings."},{"name":"Vintners'' Holidays at The Ahwahnee","source":"https://www.travelyosemite.com/things-to-do/specialty-events/holiday-events/vintners-holidays","accessed":"2026-10-02","si":["wine","culinary","romance","senior"],"booking_route":"own booking links on travelyosemite.com; dining packages booked separately from lodging","tier_absent_reason":"not-sold","blurb":"Four November 2026 sessions (8-11, 11-13, 15-18, 18-20 Nov) of seminar tastings led by Master Sommeliers, a Meet the Vintners reception and a five-course paired Gala dinner inside the park."},{"name":"Mountain Room, Yosemite Valley Lodge","source":"https://www.travelyosemite.com/dining/","accessed":"2026-10-02","si":["culinary","romance","family"],"booking_route":"own form via travelyosemite.com dining, or (888) 413-8869","tier_absent_reason":"not-sold","blurb":"Upscale-casual dinner restaurant at Yosemite Valley Lodge with views of Yosemite Falls."},{"name":"Moonlight Special dinner train, Yosemite Mountain Sugar Pine Railroad, Fish Camp","source":"https://www.ymsprr.com/","accessed":"2026-10-02","si":["culinary","family","romance","group","senior"],"booking_route":"FareHarbor","tier_absent_reason":"not-sold","blurb":"Three-hour evening outing: dinner at Yosemite Mountain Depot, then a ride on The Logger steam train with a stop at Lewis Creek Canyon for entertainment; from $95.40 per person on select dates April to December."},{"name":"Evergreen Lodge Restaurant, Groveland","source":"https://www.evergreenlodge.com/dine/restaurant/","accessed":"2026-10-02","si":["culinary","family","romance"],"booking_route":"OpenTable, phone (209) 379-2606, or walk-in subject to availability","tier_absent_reason":"not-sold","blurb":"Classic mountain cuisine with a California twist using seasonal, local, organic ingredients, served in a dining room, tavern and heated patio on the border of the park."},{"name":"1850 Restaurant + Brewing Company, Mariposa","source":"https://www.1850restaurant.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"phone only (209) 966-2229; no online reservations","tier_absent_reason":"not-sold","blurb":"Independent craft brewery and restaurant on Highway 140 pouring its own beer; fast-casual lunch, full-service dinner, dog-friendly patio."},{"name":"South Gate Brewing Company, Oakhurst","source":"https://www.southgatebrewco.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"OpenTable","tier_absent_reason":"not-sold","blurb":"Brewery and full kitchen (steak, burgers, wood-fired pizza) serving Oakhurst since 2013, with a tasting room whose big windows look out on the Sierra Nevada."},{"name":"Charles Street Dinner House, Mariposa","source":"https://www.charlesstreetdinnerhouse.com/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"phone only (209) 966-2366","tier_absent_reason":"not-sold","blurb":"Family-friendly Mariposa steakhouse serving Certified Angus beef, fresh pasta and baby back ribs, with wine, beer and cocktails."},{"name":"Priest Station Cafe, Big Oak Flat","source":"https://www.prieststation.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Cafe at 16756 Old Priest Grade, Big Oak Flat, with six generations of family ownership, open daily 8am-8pm."},{"name":"Sierra Cider Farm and Cidery, Mariposa","source":"https://www.sierracider.com/","accessed":"2026-10-02","si":["culinary","family","wine","group"],"booking_route":"walk-in during tasting-room hours (Fri-Sun); tours and tastings bookable through Airbnb Experiences","tier_absent_reason":"not-sold","blurb":"Orchard growing 20 apple varieties with a hard-cider tasting room, guided orchard tours, weekend petting zoo and apple picking on select weekends August to December at $3 a pound."},{"name":"CostaLivos Mountain Gold Olive Oil, Mariposa","source":"https://www.yosemite.com/things-to-do/restaurants/costalivos-mountain-gold-olive-oil/","accessed":"2026-10-02","si":["culinary","senior"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Extra virgin olive oils hand-picked and cold-pressed from the company''s own Sierra Nevada grove, tasted at its downtown Mariposa storefront alongside its La Cucina Italia restaurant, per the county visitor bureau listing."},{"name":"Casto Oaks Fine Wine and Art, Mariposa","source":"https://www.castooakswine.com/","accessed":"2026-10-02","si":["wine","culture","romance"],"booking_route":"walk-in tasting room; winery appointments by phone (209) 377-8450 or email","tier_absent_reason":"not-sold","blurb":"Small family winery making wines from Mariposa County grapes, with complimentary tastings at its gallery tasting room on Highway 140 in historic downtown Mariposa (closed Tuesday and Wednesday)."},{"name":"Silver Fox Vineyards, Mariposa","source":"https://www.yosemite.com/things-to-do/leisure-activities/silver-fox-vineyards/","accessed":"2026-10-02","si":["wine","romance"],"booking_route":"phone only, by appointment (209) 966-4800","tier_absent_reason":"not-sold","blurb":"Winery established in 1989 at 3,000 feet making Cabernet Sauvignon, Merlot and Rhone varietals, open by appointment only, per the county visitor bureau listing."},{"name":"Mariposa Farmers'' Market","source":"https://www.mariposafarmersmarket.com/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"State-certified market at 5029 Stroming Road selling produce, meats, honey and baked goods; Wednesdays 4:30-6:30pm May to October, 1st and 3rd Wednesdays 3-5pm November to April."}],"faq":[{"q":"Do I need a reservation to drive into Yosemite in 2026?","a":"No. The NPS announced it will no longer use a timed reservation system in 2026, and is managing access through real-time traffic monitoring, parking management and extra staffing at peak periods. It recommends planning ahead for weekends and holidays and considering weekday visits.","source":"https://www.nps.gov/yose/planyourvisit/reservations.htm","accessed":"2026-10-02"},{"q":"How do I get a permit to hike Half Dome?","a":"Permits are required seven days a week while the cables are up, with a maximum of 300 hikers a day. The preseason lottery runs March 1 through March 31 with results in mid-April; it costs a $10 non-refundable application fee plus $10 per person if a permit is awarded.","source":"https://www.nps.gov/yose/planyourvisit/hdpermits.htm","accessed":"2026-10-02"},{"q":"How do I book a campsite inside Yosemite?","a":"All thirteen NPS campgrounds list reservations as required in season. Most Yosemite Valley, Wawona and Hodgdon Meadow sites are released 5 months ahead on the 15th, Camp 4 one week ahead, and the Tioga Road campgrounds two weeks ahead. For 2026 the park said all front-country campgrounds are reservable on Recreation.gov.","source":"https://www.nps.gov/yose/planyourvisit/campground.htm","accessed":"2026-10-02"},{"q":"Where can I go glamping near Yosemite?","a":"Mariposa County''s tourism site lists AutoCamp (Airstreams and tents, Midpines), Wildhaven (tents and cabins, Mariposa), Indian Flat''s Jupe tents (El Portal), Yosemite Bug tent cabins (Midpines), Tenaya''s Explorer Cabins (Fish Camp) and in-park Curry Village and High Sierra Camps. On Highway 120, Under Canvas Yosemite sits 10 minutes from the Big Oak Flat entrance.","source":"https://www.yosemite.com/glamping-in-yosemite-mariposa-county/","accessed":"2026-10-02"},{"q":"How much does it cost to enter Yosemite?","a":"$35 per private vehicle for seven days, $30 per motorcycle, $20 per person on foot or bicycle, or $70 for an annual pass. Non-US residents aged 16 and over pay an extra $100 each unless they hold an annual or America the Beautiful pass. Cash is not accepted.","source":"https://www.nps.gov/yose/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I get to Yosemite without a car?","a":"Yes. YARTS runs buses to Yosemite Valley from Merced and Mariposa on Highway 140, Tuolumne County on Highway 120, Mono County on Highway 395/120E, and Fresno and Madera County on Highway 41.","source":"https://www.yarts.com/","accessed":"2026-10-02"}],"seo":{"meta_title":"Yosemite National Park: Half Dome, Glamping & Gateway Towns | TravelWell","meta_description":"No entry reservation in 2026, the Half Dome lottery, how NPS campsites release, and every glamping camp from Groveland to Bass Lake.","slug":"yosemite-national-park-california","primary_keyword":"Yosemite National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Yosemite Valley, Yosemite National Park, California"}}'::jsonb, 91),
  ('sequoia-california', '12A', 'Sequoia National Park', 'United States', 'The largest tree on Earth by volume, a granite dome with a historic stairway, a marble cave and the Kaweah River foothills, with Three Rivers at the gate and Visalia''s tables and taprooms below', 'future', 'verified', 'mountainValley', 'Central Coast & the Sierra', '{"hiking","family","adventure","culinary","senior","parks"}', '{"dramatic","wild","alpine","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"General Sherman Tree","source":"https://www.nps.gov/places/000/general-sherman-tree.htm","accessed":"2026-10-02","si":["family","senior","hiking"],"booking_route":"none needed - park entrance fee only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The General Sherman Tree contains more wood (volume) in its trunk than any other tree on Earth\", about 2,200 years old; \"about a half mile from the parking lot\" with an uphill return, or an accessible paved path \"about 500 feet in length and is gently sloped\"; NPS: \"bears can be active in this parking lot\""},{"name":"Congress Trail","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 2.7-mile loop from the Sherman Tree parking lot or shuttle stop through the Giant Forest sequoias, the largest unlogged grove; listed among NPS ranger recommendations"},{"name":"Big Trees Trail","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["family","senior","hiking"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 1.1-mile loop from the Giant Forest Museum parking lot, one of the NPS''s ranger-recommended Giant Forest walks"},{"name":"Moro Rock","source":"https://www.nps.gov/places/000/moro-rock.htm","accessed":"2026-10-02","si":["hiking","adventure","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a granite dome in Giant Forest whose stairway is on the National Register of Historic Places; 0.4 mile from the trailhead (plus a 3.2-mile road walk from Giant Forest Museum when the road is closed); NPS: \"Avoid climbing if snow or ice are present. Stay away from Moro Rock during thunderstorms or if there''s static in the air.\""},{"name":"Tunnel Log","source":"https://www.nps.gov/thingstodo/tunnel-log.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a fallen giant sequoia carved through so cars could pass, driven through \"Since 1935\", 0.5 mile past Moro Rock; \"Vehicles taller than 8 feet (2.4 m) can use a bypass\"; the road \"generally opens by the Wednesday before Memorial Day\""},{"name":"Crystal Cave","source":"https://www.nps.gov/seki/planyourvisit/crystal-cave.htm","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"online only via Sequoia Parks Conservancy (sequoiaparksconservancy.org), at least 36 hours ahead","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a marble cave seen only on a guided tour of about 50 minutes on a half-mile loop; \"Bring jackets; the temperature inside is 50 degrees F (10 degrees C)\"; \"Tickets are not available at the cave\"; vehicles over 22 feet cumulative length not allowed on Cave Road; tours ended for 2026, expected back late spring 2027"},{"name":"Crescent Meadow and Tharp''s Log","source":"https://www.nps.gov/thingstodo/crescent-meadow.htm","accessed":"2026-10-02","si":["hiking","family","wildlife","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a meadow loop of \"about 1.8 miles round trip\" at the end of Moro Rock / Crescent Meadow Road, to Tharp''s Log, \"a cabin built onto a hollowed-out sequoia in 1858\"; on weekends \"shuttles are the only way to reach Moro Rock and Crescent Meadow\"; \"partially paved and may be accessible, depending on abilities\"; NPS: \"Bears are common to see in meadows, especially in the spring and early summer\""},{"name":"Mineral King","source":"https://www.nps.gov/seki/planyourvisit/mineral-king.htm","accessed":"2026-10-02","si":["expedition","hiking","wildlife","adventure"],"booking_route":"none needed; local wilderness permits at the Mineral King Ranger Station","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a subalpine valley open \"seasonally from late May through October\"; \"Mineral King Road is extremely narrow, steep, winding, and unpaved in some areas\" and \"RVs and trailers are not advised\"; \"Trails here are solitary, remote, and strenuous\"; marmots \"have been known to dine on radiator hoses and car wiring\"; nearest gas in Three Rivers about 30 miles and 1.5 hours away; road delays and closures for the rest of the 2026 season"},{"name":"Lodgepole Campground","source":"https://www.nps.gov/seki/planyourvisit/lodgepole.htm","accessed":"2026-10-02","si":["family","hiking","group"],"booking_route":"recreation.gov or 877-444-6777","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the central Sequoia campground at 6,700 feet with showers and laundry nearby, beside the Lodgepole Market, open seasonally May to October; \"Site reservations are available online at recreation.gov or by phone at 877-444-6777\""},{"name":"Tokopah Falls Trail, Lodgepole","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 3.8-mile round trip from the trailhead across the road bridge from the Lodgepole Campground parking lot, on the NPS ranger recommendations list"},{"name":"Marble Falls Trail, Foothills","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 6.2-mile round trip from Potwisha Campground near site #14, in the low Foothills; NPS: \"Drowning is the primary cause of death in the parks. Rocks near rivers are slippery.\""},{"name":"Hospital Rock Picnic Area","source":"https://www.nps.gov/places/000/hospital-rock-picnic-area.htm","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Foothills picnic area by the Middle Fork of the Kaweah, \"usually warm and dry throughout the year\", with outdoor exhibits on Native American history - the place called Pah-din - plus accessible restrooms, grills, water and RV parking; the Paradise Creek Trail starts nearby"},{"name":"Giant Forest Museum and Foothills Visitor Center","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["family","senior","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the two Sequoia visitor centres open 9 am to 4:30 pm in the NPS spring schedule, each with a Sequoia Parks Conservancy park store; Foothills has free public Wi-Fi; Giant Forest Museum issues self-serve wilderness permits and lends wheelchairs"},{"name":"Potwisha Campground","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"recreation.gov (www.recreation.gov/camping/gateways/2931) or (877) 444-6777","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the Foothills campground listed as \"Open year-round\", the only campground with a dump station; NPS campsites are $32 a night for up to six people, reserved on recreation.gov; \"Roadside camping is not permitted in the parks\""},{"name":"Wilderness permits and backpacking","source":"https://www.nps.gov/seki/planyourvisit/wilderness_permits.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Wilderness permits cost $15 each trip plus $5 per person within the quota season\" (May 22 to September 26, 2026), reservable on recreation.gov up to six months ahead, released daily at 7:00 AM Pacific; walk-ups from 1:00 pm the day before; \"bear canisters ... are still required in most of the park\""},{"name":"Montecito Sequoia Lodge and Stony Creek Lodge","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02","si":["family","group"],"booking_route":"phone (operator sites not checked this build)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two lodges named in the NPS trip planner on the Sequoia National Forest stretch of Generals Highway: Montecito Sequoia, \"cabins, a restaurant, a hotel, and Wi-Fi\" ((559) 565-3388); Stony Creek, \"room rentals, a market, and a gas station\" ((559) 565-3909); both seasonal"},{"name":"Wuksachi Lodge","source":"https://www.visitsequoia.com/stay/lodging/wuksachi-lodge/","accessed":"2026-10-02","si":["family","senior","romance"],"booking_route":"visitsequoia.com online booking or (866) 807-3598","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the in-park lodge, open year-round and operated by Delaware North: \"102 spacious guest rooms\" in Standard, Deluxe and Superior categories, a \"90-seat full-service restaurant and lounge\" with an \"oversized stone fireplace\"; ADA-compliant rooms in all categories; no central air conditioning at this elevation, fans provided"},{"name":"The Peaks Restaurant and Pizza Deck, Wuksachi","source":"https://www.visitsequoia.com/","accessed":"2026-10-02","si":["culinary","family","romance"],"booking_route":"walk-in; lodge reservations (866) 807-3598","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the concessioner''s \"upscale dining at Wuksachi\" serving Sierra alpine cuisine with forest views, plus the Wuksachi Pizza Deck and the Lodgepole Grill, Market and Snack Bar; the Lodgepole Market rents tents, sleeping bags, stoves and trekking poles"},{"name":"Sequoia Adventure Tour (Sequoia Parks Conservancy)","source":"https://sequoiaparksconservancy.org/adventure/sequoia-adventure-tour/","accessed":"2026-10-02","si":["family","senior","group","hiking"],"booking_route":"FareHarbor (via the Book Now button)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"A customized adventure with your own knowledgeable guide\" through Giant Forest from the park''s nonprofit partner: 2 to 6 hours, up to 8 people, $150 per hour with a 2-hour minimum"},{"name":"Pear Lake Winter Hut","source":"https://sequoiaparksconservancy.org/adventure/pear-lake-winter-hut/","accessed":"2026-10-02","si":["expedition","adventure"],"booking_route":"FareHarbor, reservations open December 9 at 9:00 AM","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a ten-bunk backcountry hut 6 miles from Wolverton (7,200 ft) to Pear Lake (9,200 ft), $75 per person per night, February 6 to April 5 in 2026; \"for experienced backcountry skiers and snowshoers only\"; \"avalanche conditions exist at all times on the trail\"; \"There are NO REFUNDS or date changes\""},{"name":"Sequoia Parks Conservancy Field Institute","source":"https://sequoiaparksconservancy.org/","accessed":"2026-10-02","si":["wildlife","family","culture"],"booking_route":"sequoiaparksconservancy.org/adventures-events/","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"naturalist-led adventures and events such as the Sequoia Foothills River Walk, Stargazing at Lake Kaweah and the Christmas Bird Count, run by the park''s partner organisation"},{"name":"All-Outdoors Kaweah River Rafting, Three Rivers","source":"https://www.aorafting.com/river/kaweah/welcome.htm","accessed":"2026-10-02","si":["adventure","group","sports"],"booking_route":"online booking portal or (800) 247-2387","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a one-day trip on \"Class IV+ | Fast-Paced Intricate Whitewater\" from Three Rivers Hideaway Camp, mid-April through June (snowmelt dependent), minimum age 15, $244 per person; one of five outfitters listed as permitted on the Kaweah"},{"name":"Three Rivers Hideaway","source":"https://www.threerivershideaway.com/","accessed":"2026-10-02","si":["family","adventure","group"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a full service RV Park, with cabins & campground\" on the Kaweah River, open year-round, \"3.5 miles from the Foothills Entrance (Hwy. 198) to Sequoia National Park and 5 miles from Lake Kaweah\"; the rafting meet point for All-Outdoors"},{"name":"Gateway Restaurant & Lodge, Three Rivers","source":"https://www.gateway-sequoia.com/","accessed":"2026-10-02","si":["culinary","romance","group"],"booking_route":"own restaurant reservation system and lodging booking platform; (559) 561-4133","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a cozy seven-room lodge with a restaurant that serves breakfast, lunch and dinner options in both casual and fine-dining settings\" on the Kaweah River at 45978 Sierra Drive, bar open until midnight, with banquet and reception services"},{"name":"Sequoia Guides","source":"https://www.sequoiaguides.com/","accessed":"2026-10-02","si":["hiking","senior","family","group"],"booking_route":"email or call/text (559) 556-4936, then PayPal invoice","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"private guiding by lead guide Krista Simonic under NPS Commercial Use Permit #SEKI-FC-2026-01: day hiking from $400 a group, stargazing from $175, snowshoeing December-March from $350, step-on tours for motor coaches, and wheelchair accessible tours; \"Every private tour plants a tree\""},{"name":"Sequoia Sightseeing Tours, Three Rivers","source":"https://www.sequoiatours.com/","accessed":"2026-10-02","si":["senior","family","group"],"booking_route":"Bookeo (bookeo.com/sequoia-tours)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Small-group experiences using comfortable air-conditioned 10-passenger vans\": Sequoia Majesty from Three Rivers year-round, Sequoia Splendor from Wuksachi Lodge (April 26-October 30), and private full-day and winter tours"},{"name":"Keifers Giant Sequoia Tours","source":"https://giantsequoiatours.com/","accessed":"2026-10-02","si":["senior","family","romance"],"booking_route":"email (keifers@giantsequoiatours.com) or (559) 305-5318","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"private tours into Sequoia and Kings Canyon \"using luxurious SUVs with experienced former park rangers\": a full-day Sequoia tour, a half-day Giant Sequoia tour and a half-day Winter Wonderland tour; Visit Visalia lists year-round tours for groups of 1-6"},{"name":"Big Trees Tours","source":"https://www.bigtreestours.com/","accessed":"2026-10-02","si":["wildlife","hiking","family","romance"],"booking_route":"FareHarbor; telescope experience via Airbnb only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided experiences led by a local wildlife biologist: the 3-hour easy Heart of the Giant Forest Hike from the Sherman Tree parking area, and one-hour group stargazing near Potwisha Campground"},{"name":"AutoCamp Sequoia, Three Rivers","source":"https://autocamp.com/location/sequoia/","accessed":"2026-10-02","si":["glamping","romance","family","group"],"booking_route":"own website (engine not identified on the page read)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"glamping at 40457 Sierra Drive on a river bend: Airstreams, cabins, BaseCamps that pair an Airstream suite with a canvas tent, and bunk rooms; pool and river access, a clubhouse, bike rentals, EV charging, a Kitchen and General Store, complimentary granola and coffee, and arranged park tours and onsite yoga"},{"name":"Sequoia RV Ranch, Three Rivers","source":"https://www.sequoiarvranch.com/","accessed":"2026-10-02","si":["family","group"],"booking_route":"own online booking engine; 1-559-561-4333","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a riverside RV park \"only 8 miles from the entrance of Sequoia National Park\" with Deluxe River Sites, Premium Pull Thrus, water and electric sites and dry camping for RVs and tents, a spring-fed swimming hole and fishing hole, laundry and a dog park"},{"name":"Lemon Cove Village RV Park, Lemon Cove","source":"https://www.lemoncovevillagervpark.com/","accessed":"2026-10-02","si":["family","senior"],"booking_route":"ResNexus (reserve5.resnexus.com); (559) 370-4152","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a year-round Good Sam park with full hookups, level pull-through sites, a swimming pool, gemstone mining and fossil dig; \"Walk-ins welcome. Reservations encouraged, but not necessary\"; about 19 miles east of Visalia"},{"name":"Kaweah Oaks Preserve, near Visalia","source":"https://sequoiariverlands.org/visit-our-preserves/kaweah-oaks/","accessed":"2026-10-02","si":["wildlife","family","hiking","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"344 acres protecting \"one of the last remaining valley oak riparian forests in the San Joaquin Valley\", seven miles east of downtown Visalia off Highway 198; free, open \"Sunrise to Sunset 365 Days a Year\"; \"over 300 plant and animal species including bobcats, great horned owls\"; no bicycles or horses; run by Sequoia Riverlands Trust"},{"name":"Riata Ranch International, Three Rivers","source":"https://visitvisalia.com/tours-and-rentals","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"contact page or (559) 303-0729; no online booking or rates seen","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"listed by Visit Visalia for \"Trail rides in Sierra Nevada foothills along the North Fork of the Kaweah River\"; the ranch at 42390 North Kaweah River Road offers \"Horseback riding, training, and adventure\""},{"name":"Kaweah Marina, Lake Kaweah, Lemon Cove","source":"http://www.kaweahmarina.com/","accessed":"2026-10-02","si":["family","adventure","group"],"booking_route":"FareHarbor only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"patio boats, aqua cycles, kayaks and paddle boards available for rent\" on Lake Kaweah off Highway 198; winter hours mid-September to March 9am-4pm, closed Mondays and Tuesdays"},{"name":"The Vintage Press, Visalia","source":"https://www.thevintagepress.com/","accessed":"2026-10-02","si":["culinary","wine","romance"],"booking_route":"Resy, or 559.733.3033","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"farm-to-fork restaurant open since 1966 at 216 N Willis Street, with over 900 wines and what Wine Spectator calls \"one of the best wine lists in the world\""},{"name":"Visalia Craft Beer Trail","source":"https://visitvisalia.com/beer-wine","accessed":"2026-10-02","si":["culinary","wine","group"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a downtown brewery district trail with BarrelHouse Brewing Co. and Brewbakers Brewing Co., and \"Visalia''s newest tap rooms\" Salty Walrus and Long Shot; wine rooms include Blend Wine Room and Wine Buff Tasting Room"},{"name":"We Three Bakery, Three Rivers","source":"https://californiawhitewater.com/rivers/kaweah/restaurants","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a local bakery at 43370 Sierra Drive with \"coffee and baked goods for early risers\" that packs lunches for the river or the park; patio dining; closed Tuesdays"},{"name":"Sequoia Cider Mill Restaurant, Three Rivers","source":"https://californiawhitewater.com/rivers/kaweah/restaurants","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in; (559) 561-4157","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a family restaurant at 40311 Sierra Drive serving breakfast, lunch and dinner daily; \"Specialize in grilled meats and Mexican food\""},{"name":"Serrano''s Mexican Restaurant, Three Rivers","source":"https://californiawhitewater.com/rivers/kaweah/restaurants","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"walk-in; (559) 561-7283","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"daily breakfast, lunch and dinner at 40869 Sierra Drive, from \"burritos and tacos to full seafood dinners\", with patio dining"}],"faq":[{"q":"Do I need a reservation to enter Sequoia National Park?","a":"No. The NPS states that reservations are not accepted or required. A private vehicle pays $35 for 1-7 days.","source":"https://www.nps.gov/seki/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Is there an extra fee for international visitors?","a":"Yes. The NPS states that each non-US resident aged 16 and older must pay a $100 nonresident fee in addition to the standard entrance fee, unless admitted with an Annual or America the Beautiful Pass. The Non-Resident America the Beautiful Annual Pass is $250.","source":"https://www.nps.gov/seki/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Is Crystal Cave open?","a":"Not now. The NPS states that guided tours of Crystal Cave have ended for the 2026 season and are expected to begin again in late spring of 2027. Tickets are sold online only through the Sequoia Parks Conservancy and are not available at the cave.","source":"https://www.nps.gov/seki/planyourvisit/crystal-cave.htm","accessed":"2026-10-02"},{"q":"Can I drive an RV to Moro Rock or Crystal Cave?","a":"Not a long one. The NPS lists a 22-foot restriction on Moro Rock / Crescent Meadow Road, with longer vehicles not allowed, and vehicles over 22 feet cumulative length are not allowed on Crystal Cave Road. It recommends 22 feet on Generals Highway from Potwisha Campground to Giant Forest.","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02"},{"q":"How far is the General Sherman Tree from the parking lot?","a":"The NPS says it is about a half mile from the main parking lot, with an uphill return; an accessible paved path of about 500 feet, gently sloped, leads from the accessible parking on Generals Highway.","source":"https://www.nps.gov/places/000/general-sherman-tree.htm","accessed":"2026-10-02"},{"q":"Which campground is open all year?","a":"The NPS lists Potwisha Campground in the Foothills as open year-round. Standard sites are $32 a night and reservations are made on recreation.gov.","source":"https://nps.gov/seki/learn/news/upload/Trip_Planner_2026_Spring_2026-03-19_01_for_web_508.pdf","accessed":"2026-10-02"}],"seo":{"meta_title":"Sequoia National Park: General Sherman, Moro Rock, Crystal Cave & Where to Stay | TravelWell","meta_description":"The General Sherman Tree, Moro Rock, Crystal Cave, current closures and fees, NPS campgrounds, and where to stay from Wuksachi Lodge to Three Rivers glamping.","slug":"sequoia-national-park-california","primary_keyword":"Sequoia National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Sequoia National Park, California"}}'::jsonb, 92)
